  <script>
    // 状态管理
    const state = {
      personalTaxDeposited: false,
      enterpriseTaxDeposited: false,
      get totalDeposited() {
        return (this.personalTaxDeposited ? 1 : 0) + (this.enterpriseTaxDeposited ? 1 : 0);
      }
    };

    // DOM 元素
    const coins = document.querySelectorAll('.coin');
    const dropzone = document.getElementById('treasury-dropzone');
    const infoPanel = document.getElementById('info-panel');
    const glow = document.getElementById('treasury-glow');
    const guideBox = document.getElementById('guide-box');
    const btnReset = document.getElementById('btn-reset');

    const facilityGroups = {
      highway: document.getElementById('group-highway'),
      park: document.getElementById('group-park'),
      school: document.getElementById('group-school')
    };

    // 声音合成器 (Web Audio API) - 增加趣味性
    function playSound(type) {
      try {
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        if (type === 'coin') {
          // 金币落袋声
          const osc = ctx.createOscillator();
          const gain = ctx.createGain();
          osc.type = 'sine';
          osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
          osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + 0.1); // A5
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
          osc.connect(gain);
          gain.connect(ctx.destination);
          osc.start();
          osc.stop(ctx.currentTime + 0.3);
        } else if (type === 'success') {
          // 成功点亮声
          [523.25, 659.25, 783.99, 1046.50].forEach((freq, i) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(freq, ctx.currentTime + i * 0.08);
            gain.gain.setValueAtTime(0.08, ctx.currentTime + i * 0.08);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + i * 0.08 + 0.4);
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(ctx.currentTime + i * 0.08);
            osc.stop(ctx.currentTime + i * 0.08 + 0.4);
          });
        }
      } catch (e) {
        // 忽略不支持Web Audio的浏览器
      }
    }

    // 拖拽逻辑实现 (兼容桌面与移动端 Pointer Events)
    coins.forEach(coin => {
      let isDragging = false;
      let startX, startY;
      let initialX = 0, initialY = 0;

      coin.addEventListener('pointerdown', (e) => {
        isDragging = true;
        coin.setPointerCapture(e.pointerId);

        // 记录初始指针位置
        startX = e.clientX;
        startY = e.clientY;

        coin.style.transition = 'none';
        coin.style.zIndex = '1000';
      });

      coin.addEventListener('pointermove', (e) => {
        if (!isDragging) return;

        const dx = e.clientX - startX;
        const dy = e.clientY - startY;

        coin.style.transform = `translate(${initialX + dx}px, ${initialY + dy}px) scale(1.1)`;
      });

      coin.addEventListener('pointerup', (e) => {
        if (!isDragging) return;
        isDragging = false;
        coin.releasePointerCapture(e.pointerId);

        // 检测是否碰撞到财政库
        const coinRect = coin.getBoundingClientRect();
        const dropzoneRect = dropzone.getBoundingClientRect();

        const isOverlapping = !(
          coinRect.right < dropzoneRect.left ||
          coinRect.left > dropzoneRect.right ||
          coinRect.bottom < dropzoneRect.top ||
          coinRect.top > dropzoneRect.bottom
        );

        if (isOverlapping) {
          // 成功放入
          const taxType = coin.dataset.type;
          handleTaxDeposit(taxType, coin);
        } else {
          // 弹回原位
          resetCoinPosition(coin);
        }
      });
    });

