      // --- 触摸/指针拖拽实现 (更平滑的白板体验) ---
      let activePointerCard = null;
      let pointerOffsetX = 0;
      let pointerOffsetY = 0;
      let initialCardRect = null;

      function handlePointerDown(e) {
        // 仅当卡片在左侧面板时允许拖拽
        if (this.parentElement !== sourcePanel) return;

        activePointerCard = this;
        this.setPointerCapture(e.pointerId);

        const rect = this.getBoundingClientRect();
        pointerOffsetX = e.clientX - rect.left;
        pointerOffsetY = e.clientY - rect.top;

        this.style.position = 'fixed';
        this.style.width = `${rect.width}px`;
        this.style.height = `${rect.height}px`;
        this.style.left = `${e.clientX - pointerOffsetX}px`;
        this.style.top = `${e.clientY - pointerOffsetY}px`;
        this.classList.add('dragging');

        this.addEventListener('pointermove', handlePointerMove);
        this.addEventListener('pointerup', handlePointerUp);
        this.addEventListener('pointercancel', handlePointerUp);
      }

      function handlePointerMove(e) {
        if (!activePointerCard) return;
        activePointerCard.style.left = `${e.clientX - pointerOffsetX}px`;
        activePointerCard.style.top = `${e.clientY - pointerOffsetY}px`;

        // 碰撞检测高亮
        dropZones.forEach(zone => {
