        valRate.textContent = `${rate}%`;
        valTax.textContent = `${tax.toFixed(1)}万`;

        // 3. 更新右侧 SVG 比例图
        // 设定最大计税收入 1000万 对应柱状图高度 220px
        const maxIncome = 1000;
        const maxBarHeight = 220;
        const baselineY = 270; // 底部基准线 Y 坐标

        // 计算计税收入柱状图的高度和Y坐标
        const incomeHeight = (income / maxIncome) * maxBarHeight;
        const incomeY = baselineY - incomeHeight;

        rectIncome.setAttribute('height', incomeHeight);
        rectIncome.setAttribute('y', incomeY);

        // 计算应纳税额柱状图的高度和Y坐标 (它是计税收入的一部分)
        const taxHeight = incomeHeight * (rate / 100);
        const taxY = baselineY - taxHeight;

