            请对比以下两种算式，点击卡片或下方按钮，观察工资条的拆分变化：
        </div>
    </div>

    <!-- 主工作区 -->
    <div class="workspace">
        <!-- 算式对比卡片 -->
        <div class="formula-container">
            <div class="formula-card" id="card-f1">
                <div class="formula-badge">不合理</div>
                <div class="formula-title">算式 ①</div>
                <div class="formula-body">8000 × 3%</div>
            </div>
            <div class="formula-card" id="card-f2">
                <div class="formula-badge">合理</div>
                <div class="formula-title">算式 ②</div>
                <div class="formula-body"><span id="formula-part-excess" class="">(8000 - 5000)</span> × 3%</div>
            </div>
        </div>

        <!-- SVG 交互直观模型 -->
        <div class="canvas-container">
            <svg viewBox="0 0 800 240" id="svg-model">
                <!-- 渐变定义 -->
                <defs>
                    <linearGradient id="blue-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stop-color="#3498db" />
                        <stop offset="100%" stop-color="#2980b9" />
                    </linearGradient>
                    <linearGradient id="green-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stop-color="#2ecc71" />
                        <stop offset="100%" stop-color="#27ae60" />
                    </linearGradient>
                    <linearGradient id="orange-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stop-color="#e67e22" />
                        <stop offset="100%" stop-color="#d35400" />
                    </linearGradient>
                </defs>

                <!-- 背景网格/辅助线 -->
                <line x1="100" y1="180" x2="700" y2="180" stroke="#bdc3c7" stroke-width="2" stroke-dasharray="5,5" />

                <!-- 刻度尺 -->
                <text x="100" y="200" font-size="12" fill="#7f8c8d" text-anchor="middle">0元</text>
                <text x="475" y="200" font-size="12" fill="#7f8c8d" text-anchor="middle" id="scale-threshold">5000元(起征点)</text>
                <text x="700" y="200" font-size="12" fill="#7f8c8d" text-anchor="middle">8000元(总工资)</text>

                <!-- 1. 免税部分矩形 (左) -->
                <rect id="rect-free" x="100" y="60" width="375" height="80" rx="6" fill="url(#blue-grad)" transition="all 0.5s" />
                <!-- 2. 计税部分矩形 (右) -->
                <rect id="rect-tax" x="475" y="60" width="225" height="80" rx="6" fill="url(#blue-grad)" transition="all 0.5s" />

                <!-- 剪刀分割线 -->
                <line id="split-line" x1="475" y1="40" x2="475" y2="160" stroke="#e74c3c" stroke-width="3" stroke-dasharray="6,4" opacity="0" />
                <text id="split-scissor" x="465" y="35" font-size="20" opacity="0">✂️</text>

                <!-- 动态文字标签 -->
                <!-- 总工资标签 -->
                <text id="label-total" x="400" y="105" font-size="20" font-weight="bold" fill="#ffffff" text-anchor="middle" pointer-events="none">总工资 8000 元</text>

                <!-- 免税额标签 -->
                <text id="label-free" x="287" y="105" font-size="16" font-weight="bold" fill="#ffffff" text-anchor="middle" opacity="0" pointer-events="none">免税部分 5000元</text>

                <!-- 计税额标签 -->
                <text id="label-taxable" x="587" y="105" font-size="16" font-weight="bold" fill="#ffffff" text-anchor="middle" opacity="0" pointer-events="none">超出部分 3000元</text>
                <text id="label-taxable-sub" x="587" y="125" font-size="12" fill="#ffffff" text-anchor="middle" opacity="0" pointer-events="none">(8000 - 5000)元</text>

                <!-- 括号指示器 -->
                <path id="bracket-free" d="M 102 150 L 102 160 L 287 160 L 287 165 L 287 160 L 473 160 L 473 150" fill="none" stroke="#27ae60" stroke-width="2" opacity="0" />
                <path id="bracket-tax" d="M 477 150 L 477 160 L 587 160 L 587 165 L 587 160 L 698 160 L 698 150" fill="none" stroke="#d35400" stroke-width="2" opacity="0" />
            </svg>
        </div>

        <!-- 交互控制面板 -->
        <div class="control-panel">
            <div class="slider-group">
                <div class="slider-label">
                    <span>起征点调整:</span>
                    <span id="threshold-val" style="color: var(--primary-color);">5000 元</span>
                </div>
                <input type="range" id="threshold-slider" class="slider-input" min="1000" max="7000" step="500" value="5000">
            </div>
            <div class="btn-group">
                <button class="btn btn-secondary" id="btn-reset">🔄 还原初始状态</button>
                <button class="btn btn-primary" id="btn-show-f1">🔍 剖析算式 ① (全额征税)</button>
                <button class="btn btn-primary" id="btn-show-f2">✂️ 剖析算式 ② (超出部分征税)</button>
            </div>
        </div>
