</div>

<script>
    // 获取DOM元素
    const slider = document.getElementById('threshold-slider');
    const thresholdVal = document.getElementById('threshold-val');
    const scaleThreshold = document.getElementById('scale-threshold');

    const rectFree = document.getElementById('rect-free');
    const rectTax = document.getElementById('rect-tax');
    const splitLine = document.getElementById('split-line');
    const splitScissor = document.getElementById('split-scissor');

    const labelTotal = document.getElementById('label-total');
    const labelFree = document.getElementById('label-free');
    const labelTaxable = document.getElementById('label-taxable');
    const labelTaxableSub = document.getElementById('label-taxable-sub');

    const bracketFree = document.getElementById('bracket-free');
    const bracketTax = document.getElementById('bracket-tax');

    const cardF1 = document.getElementById('card-f1');
    const cardF2 = document.getElementById('card-f2');
    const formulaPartExcess = document.getElementById('formula-part-excess');

    const btnReset = document.getElementById('btn-reset');
    const btnShowF1 = document.getElementById('btn-show-f1');
    const btnShowF2 = document.getElementById('btn-show-f2');

    // 常量配置
    const TOTAL_SALARY = 8000;
    const SVG_WIDTH = 600; // 对应 8000 元
    const START_X = 100;

    let currentThreshold = 5000;
    let currentMode = 'normal'; // 'normal', 'f1', 'f2'

    // 初始化渲染
    function updateVisualization() {
        // 计算比例
        const thresholdRatio = currentThreshold / TOTAL_SALARY;
        const splitX = START_X + SVG_WIDTH * thresholdRatio;

        // 更新滑块数值显示
        thresholdVal.textContent = `${currentThreshold} 元`;
        scaleThreshold.textContent = `${currentThreshold}元(起征点)`;
        scaleThreshold.setAttribute('x', splitX);

        // 动态更新算式②中的起征点数值
        formulaPartExcess.innerHTML = `(${TOTAL_SALARY} - <span style="color: var(--tax-free-color);">${currentThreshold}</span>)`;

        if (currentMode === 'normal') {
            // 恢复整条蓝色
            rectFree.setAttribute('width', splitX - START_X);
            rectFree.setAttribute('fill', 'url(#blue-grad)');

            rectTax.setAttribute('x', splitX);
            rectTax.setAttribute('width', START_X + SVG_WIDTH - splitX);
            rectTax.setAttribute('fill', 'url(#blue-grad)');

            // 隐藏辅助线和标签
            splitLine.setAttribute('opacity', '0');
            splitScissor.setAttribute('opacity', '0');
            labelTotal.setAttribute('opacity', '1');
            labelTotal.setAttribute('x', START_X + SVG_WIDTH / 2);

            labelFree.setAttribute('opacity', '0');
            labelTaxable.setAttribute('opacity', '0');
            labelTaxableSub.setAttribute('opacity', '0');

            bracketFree.setAttribute('opacity', '0');
            bracketTax.setAttribute('opacity', '0');

            // 卡片状态
            cardF1.className = 'formula-card';
            cardF2.className = 'formula-card';
            formulaPartExcess.className = '';
            rectTax.classList.remove('pulse');
        } 
        else if (currentMode === 'f1') {
            // 算式①：全额征税，整条变橙色/红色警告
            rectFree.setAttribute('width', SVG_WIDTH);
            rectFree.setAttribute('fill', 'url(#orange-grad)');
            rectTax.setAttribute('width', '0');

            splitLine.setAttribute('opacity', '0');
            splitScissor.setAttribute('opacity', '0');

            labelTotal.setAttribute('opacity', '1');
            labelTotal.textContent = `全部 8000 元都纳税！`;
            labelTotal.setAttribute('x', START_X + SVG_WIDTH / 2);

            labelFree.setAttribute('opacity', '0');
            labelTaxable.setAttribute('opacity', '0');
            labelTaxableSub.setAttribute('opacity', '0');

            bracketFree.setAttribute('opacity', '0');
            bracketTax.setAttribute('opacity', '0');

            // 卡片高亮
            cardF1.className = 'formula-card active-wrong';
            cardF2.className = 'formula-card';
            formulaPartExcess.className = '';
            rectTax.classList.remove('pulse');
        } 
        else if (currentMode === 'f2') {
            // 算式②：合理切分
            const gap = 15; // 切开的缝隙
            const leftWidth = splitX - START_X;
            const rightWidth = START_X + SVG_WIDTH - splitX;
            const taxableAmount = TOTAL_SALARY - currentThreshold;

            // 左侧免税部分（绿色）
            rectFree.setAttribute('width', leftWidth);
            rectFree.setAttribute('fill', 'url(#green-grad)');

            // 右侧计税部分（橙色，向右平移产生切开效果）
            rectTax.setAttribute('x', splitX + gap);
            rectTax.setAttribute('width', rightWidth - gap > 0 ? rightWidth - gap : 0);
            rectTax.setAttribute('fill', 'url(#orange-grad)');
            rectTax.classList.add('pulse');

            // 显示剪刀和虚线
            splitLine.setAttribute('x1', splitX + gap/2);
            splitLine.setAttribute('x2', splitX + gap/2);
            splitLine.setAttribute('opacity', '1');

            splitScissor.setAttribute('x', splitX - 5);
            splitScissor.setAttribute('opacity', '1');

            // 隐藏总工资标签，显示拆分标签
            labelTotal.setAttribute('opacity', '0');

            // 免税标签位置与数值
            const freeCenterX = START_X + leftWidth / 2;
            labelFree.setAttribute('x', freeCenterX);
            labelFree.setAttribute('opacity', '1');
            labelFree.textContent = `免税部分 ${currentThreshold}元`;

            // 计税标签位置与数值
            const taxCenterX = splitX + gap + (rightWidth - gap) / 2;
            labelTaxable.setAttribute('x', taxCenterX);
            labelTaxable.setAttribute('opacity', '1');
            labelTaxable.textContent = `超出部分 ${taxableAmount}元`;

            labelTaxableSub.setAttribute('x', taxCenterX);
            labelTaxableSub.setAttribute('opacity', '1');
            labelTaxableSub.textContent = `(${TOTAL_SALARY} - ${currentThreshold})元`;

            // 绘制大括号
            bracketFree.setAttribute('d', `M ${START_X+2} 150 L ${START_X+2} 160 L ${freeCenterX} 160 L ${freeCenterX} 165 L ${freeCenterX} 160 L ${splitX-2} 160 L ${splitX-2} 150`);
            bracketFree.setAttribute('opacity', '1');

            const bTaxStart = splitX + gap + 2;
            const bTaxEnd = START_X + SVG_WIDTH - 2;
            bracketTax.setAttribute('d', `M ${bTaxStart} 150 L ${bTaxStart} 160 L ${taxCenterX} 160 L ${taxCenterX} 165 L ${taxCenterX} 160 L ${bTaxEnd} 160 L ${bTaxEnd} 150`);
            bracketTax.setAttribute('opacity', '1');

            // 卡片高亮
            cardF1.className = 'formula-card';
            cardF2.className = 'formula-card active-correct';
            formulaPartExcess.className = 'highlight';
        }
    }

    // 事件监听
    slider.addEventListener('input', (e) => {
        currentThreshold = parseInt(e.target.value);
        updateVisualization();
    });

    btnReset.addEventListener('click', () => {
        currentMode = 'normal';
        labelTotal.textContent = "总工资 8000 元";
        updateVisualization();
    });

    btnShowF1.addEventListener('click', () => {
        currentMode = 'f1';
        updateVisualization();
    });

    btnShowF2.addEventListener('click', () => {
        currentMode = 'f2';
        updateVisualization();
    });

    cardF1.addEventListener('click', () => {
        currentMode = 'f1';
        updateVisualization();
    });

    cardF2.addEventListener('click', () => {
        currentMode = 'f2';
        updateVisualization();
    });

    // 首次加载初始化
    updateVisualization();
</script>

</body>
