                    <div class="step-card" draggable="true" id="card-1">
                        <div class="card-icon">A</div>
                        <div class="card-text">确定计税基数 = 总收入 - 免税额</div>
                    </div>
                    <!-- 卡片 2 (正确 Step 2) -->
