    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const cards = document.querySelectorAll('.step-card');
            const slots = document.querySelectorAll('.slot-box');
            const cardsPool = document.getElementById('cards-pool');
            const statusMsg = document.getElementById('status-msg');
            const btnReset = document.getElementById('btn-reset');
            const demoOverlay = document.getElementById('demo-overlay');

            // 动态演示元素
            const incomeSlider = document.getElementById('income-slider');
            const incomeValDisplay = document.getElementById('income-val-display');
            const barExempt = document.getElementById('bar-exempt');
            const barTaxable = document.getElementById('bar-taxable');
            const formulaStep1 = document.getElementById('formula-step1');
            const formulaStep2 = document.getElementById('formula-step2');

            let selectedCard = null; // 用于点击选择交互

            // 初始化卡片顺序随机化
            function shuffleCards() {
                const cardsArray = Array.from(cards);
                cardsArray.sort(() => Math.random() - 0.5);
                cardsArray.forEach(card => cardsPool.appendChild(card));
            }
            shuffleCards();

            // --- 拖拽交互实现 ---
            cards.forEach(card => {
                card.addEventListener('dragstart', (e) => {
                    card.classList.add('dragging');
                    e.dataTransfer.setData('text/plain', card.id);
                });

                card.addEventListener('dragend', () => {
                    card.classList.remove('dragging');
                });

                // 点击选择交互（兼容移动端/触屏白板）
                card.addEventListener('click', () => {
                    if (selectedCard) {
                        selectedCard.classList.remove('selected');
                    }
                    if (selectedCard === card) {
                        selectedCard = null; // 再次点击取消选择
                    } else {
                        selectedCard = card;
                        card.classList.add('selected');
                        statusMsg.innerHTML = `👉 已选择卡片，请点击左侧的 <strong>Step 1</strong> 或 <strong>Step 2</strong> 放入。`;
                    }
                });
            });

            slots.forEach(slot => {
                slot.addEventListener('dragover', (e) => {
                    e.preventDefault();
                    if (!slot.classList.contains('correct')) {
                        slot.classList.add('hovered');
                    }
                });

                slot.addEventListener('dragleave', () => {
                    slot.classList.remove('hovered');
                });

                slot.addEventListener('drop', (e) => {
                    e.preventDefault();
                    slot.classList.remove('hovered');
                    const cardId = e.dataTransfer.getData('text/plain');
                    const card = document.getElementById(cardId);
                    handlePlacement(card, slot);
                });

                // 点击槽位放入
                slot.addEventListener('click', () => {
                    if (selectedCard) {
                        handlePlacement(selectedCard, slot);
                        selectedCard.classList.remove('selected');
                        selectedCard = null;
                    }
                });
            });

            // 处理卡片放置逻辑
            function handlePlacement(card, slot) {
                if (!card || !slot) return;

                const expectedId = slot.getAttribute('data-expected');
                const slotContent = slot.querySelector('.slot-content');

                if (card.id === expectedId) {
                    // 放置正确
                    slot.classList.add('correct');
                    slotContent.innerHTML = card.querySelector('.card-text').innerText;
                    card.style.display = 'none'; // 隐藏已被正确放置的卡片
                    statusMsg.innerHTML = `<span class="success-text">💚 步骤正确！做得好！</span>`;
                    checkCompletion();
                } else {
                    // 放置错误
                    slot.style.borderColor = 'var(--danger-color)';
                    statusMsg.innerHTML = `<span class="highlight-text">❌ 步骤不匹配，请再思考一下！</span>`;
                    setTimeout(() => {
                        if (!slot.classList.contains('correct')) {
                            slot.style.borderColor = '';
                        }
                    }, 1000);
                }
            }

            // 检查是否全部完成
            function checkCompletion() {
                const slot1Correct = document.getElementById('slot-1').classList.contains('correct');
                const slot2Correct = document.getElementById('slot-2').classList.contains('correct');

                if (slot1Correct && slot2Correct) {
                    statusMsg.innerHTML = `<span class="success-text">🎉 恭喜！你已成功总结出复杂纳税问题的通用解题步骤！</span>`;
                    unlockDemo();
                }
            }

            // 解锁动态演示
            function unlockDemo() {
                demoOverlay.classList.add('unlocked');
                updateDemoVisuals();
            }

            // --- 动态演示计算逻辑 ---
            const EXEMPT_AMOUNT = 5000;
            const TAX_RATE = 0.03;

            function updateDemoVisuals() {
                const totalIncome = parseInt(incomeSlider.value);
                incomeValDisplay.innerText = `${totalIncome} 元`;

                let taxableIncome = totalIncome - EXEMPT_AMOUNT;
                if (taxableIncome < 0) taxableIncome = 0;

                const tax = taxableIncome * TAX_RATE;

                // 计算条形图比例
                const exemptPercent = (EXEMPT_AMOUNT / totalIncome) * 100;
                const taxablePercent = 100 - exemptPercent;

                if (totalIncome <= EXEMPT_AMOUNT) {
                    barExempt.style.width = '100%';
                    barExempt.innerText = `总收入 ${totalIncome}元 ≤ 免税额 ${EXEMPT_AMOUNT}元 (无需纳税)`;
                    barTaxable.style.width = '0%';
                    barTaxable.innerText = '';

                    formulaStep1.innerHTML = `${totalIncome} - ${EXEMPT_AMOUNT} ≤ 0<br><strong class="highlight-text">计税基数 = 0元</strong>`;
                    formulaStep2.innerHTML = `0 × 3% = <strong class="highlight-text">0元</strong>`;
                } else {
                    barExempt.style.width = `${exemptPercent}%`;
                    barExempt.innerText = `免税额 ${EXEMPT_AMOUNT}元`;
                    barTaxable.style.width = `${taxablePercent}%`;
                    barTaxable.innerText = `计税基数 ${taxableIncome}元`;

                    formulaStep1.innerHTML = `${totalIncome} - ${EXEMPT_AMOUNT} = <strong class="success-text">${taxableIncome}元</strong>`;
                    formulaStep2.innerHTML = `${taxableIncome} × 3% = <strong class="highlight-text">${tax.toFixed(1)}元</strong>`;
                }
            }

            incomeSlider.addEventListener('input', updateDemoVisuals);

            // 重置功能
            btnReset.addEventListener('click', () => {
                // 重置槽位
                slots.forEach(slot => {
                    slot.classList.remove('correct', 'hovered');
                    slot.style.borderColor = '';
                    const stepNum = slot.id.split('-')[1];
                    slot.querySelector('.slot-content').innerText = `请在此处放置第${stepNum === '1' ? '一' : '二'}步`;
                });

                // 重置卡片
                cards.forEach(card => {
                    card.style.display = 'flex';
                    card.classList.remove('selected');
                });
                selectedCard = null;

                // 重新打乱卡片
                shuffleCards();

                // 锁定演示区
                demoOverlay.classList.remove('unlocked');
                incomeSlider.value = 8000;

                statusMsg.innerHTML = `💡 提示：请将正确的步骤卡片拖入对应的槽位中。`;
            });
        });
    </script>
