                checkWinCondition();
            } else {
                // 分类错误：播放抖动动画
                card.classList.add('shake');
                updateFeedback(card.querySelector('.card-title').textContent, false);

                // 动画结束后移除抖动类
                card.addEventListener('animationend', () => {
                    card.classList.remove('shake');
                }, { once: true });
            }
        }

        // 更新反馈文字
        function updateFeedback(cardName, isCorrect) {
            if (isCorrect) {
                feedbackText.innerHTML = `🎉 <strong>正确！</strong>【${cardName}】分类成功。请阅读卡片上的详细解析。`;
            } else {
                feedbackText.innerHTML = `❌ <strong>不对哦。</strong>想一想【${cardName}】的建设资金是谁出的？它是以盈利为目的吗？`;
