      // 2. 更新公式卡片内的数值
      fValTax.textContent = state.tax + ' 万元';
      fValRate.textContent = state.rate + '%';

      if (state.mode === 'forward') {
        fValIncome.textContent = state.revealed ? income + ' 万元' : '? 万元';
