      }

      // 3. 公式位置与符号动画
      const currentSlots = slots[state.mode];

      termTax.style.left = currentSlots.tax.left;
      termIncome.style.left = currentSlots.income.left;
      termRate.style.left = currentSlots.rate.left;
      opEqual.style.left = currentSlots.equal.left;
      opMath.style.left = currentSlots.op.left;

      if (state.mode === 'forward') {
        opMath.textContent = '×';
