<script>
    // 获取DOM元素
    const salaryRange = document.getElementById('salary-range');
    const salaryDisplay = document.getElementById('salary-display');
    const pointerGroup = document.getElementById('pointer-group');
    const pointerText = document.getElementById('pointer-text');
    const taxableBar = document.getElementById('taxable-bar');
    const taxableBarText = document.getElementById('taxable-bar-text');
    const gateBar = document.getElementById('gate-bar');
    const gateStatus = document.getElementById('gate-status');
    const taxFlowGroup = document.getElementById('tax-flow-group');
    const flowLine = document.getElementById('flow-line');

    const wrongCalcText = document.getElementById('wrong-calc-text');
    const correctCalcText = document.getElementById('correct-calc-text');

    const btn4800 = document.getElementById('btn-4800');
    const btn5000 = document.getElementById('btn-5000');
    const btn6500 = document.getElementById('btn-6500');

    // 数轴物理参数
    // 0元对应 X=50, 8000元对应 X=710. 
    // 比例尺: 1元 = 660 / 8000 = 0.0825 像素
