    const xMax = 710;
    const valMin = 0;
    const valMax = 8000;
    const threshold = 5000;
    const xThreshold = 462.5; // 50 + 5000 * 0.0825

    function valToX(val) {
        return xMin + (val / valMax) * (xMax - xMin);
    }

    // 更新可视化状态
    function updateVisualization(salary) {
        // 1. 更新滑块和数值显示
        salaryRange.value = salary;
        salaryDisplay.textContent = salary + '元';

        // 2. 更新数轴指针位置
        const xPos = valToX(salary);
