            // 隐藏超额橙色条和流向动画
            taxableBar.setAttribute('width', '0');
            taxableBarText.setAttribute('display', 'none');
            taxFlowGroup.setAttribute('display', 'none');

            // 计算对比
            const wrongResult = ((salary - threshold) * 0.03).toFixed(2);
