            taxFlowGroup.setAttribute('display', 'block');
            // 动态调整流向线的起点
            flowLine.setAttribute('d', `M ${xThreshold + taxableWidth/2 - 600},110 Q -50,110 60,55`);

            // 计算对比
            const wrongResult = ((salary - threshold) * 0.03).toFixed(2);
            const correctTaxable = salary - threshold;
            const correctTax = (correctTaxable * 0.03).toFixed(2);

            wrongCalcText.innerHTML = `
                当工资为 <span class="highlight-num">${salary}</span> 元时：<br>
                公式：(${salary} - 5000) × 3% = <span class="highlight-num">${wrongResult} 元</span><br>
                <strong>情况：</strong> 此时因为工资超过了起征点，直接套用公式在数值上是“碰巧正确”的。
            `;

            correctCalcText.innerHTML = `
                起征点是<strong>纳税的门槛</strong>。<br>
                • 只有超出 5000 元的部分才纳税：<br>
                &nbsp;&nbsp;<span class="highlight-num">${salary} - 5000 = ${correctTaxable}元</span><br>
                • 纳税额 = 超出部分 × 3%：<br>
                &nbsp;&nbsp;<span class="highlight-num">${correctTaxable} × 3% = ${correctTax} 元</span><br>
                <strong>实际应纳税额：</strong> <span class="highlight-num" style="font-size: 18px; color:#15803d;">${correctTax} 元</span>
            `;
        }
    }

    // 切换激活按钮样式
    function setActiveButton(activeBtn) {
        [btn4800, btn5000, btn6500].forEach(btn => {
            btn.classList.remove('btn-active');
