    padding: 10px;
  }
  .slider-group {
    background: #f8fafc;
    padding: 12px;
    border-radius: 8px;
    border: 1px solid #f0f2f5;
  }
  .slider-header {
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px;
    font-size: 13px;
    font-weight: bold;
    color: #2c3e50;
  }
  .slider-header .val {
    color: #3498db;
    font-size: 15px;
  }
  .slider-input {
    width: 100%;
    height: 6px;
    border-radius: 3px;
    outline: none;
    -webkit-appearance: none;
    background: #e4e7ed;
  }
  .slider-input::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #3498db;
    cursor: pointer;
    transition: transform 0.1s;
  }
  .slider-input::-webkit-slider-thumb:hover {
    transform: scale(1.2);
  }

  /* 探究数据对比卡片 */
  .comparison-card {
    background: #fff;
    border: 1px solid #e4e7ed;
    border-radius: 8px;
    padding: 12px;
    margin-top: auto;
  }
  .comp-row {
    display: flex;
    justify-content: space-between;
    font-size: 12px;
    padding: 6px 0;
    border-bottom: 1px dashed #f0f2f5;
  }
  .comp-row:last-child {
    border-bottom: none;
  }
  .comp-label {
    color: #606266;
  }
  .comp-val {
    font-weight: bold;
    color: #2c3e50;
  }
  .comp-val.highlight {
    color: #e67e22;
  }

  /* SVG 动画与样式 */
  svg {
    width: 100%;
    height: 100%;
  }
  .bar {
    transition: y 0.6s cubic-bezier(0.25, 1, 0.5, 1), height 0.6s cubic-bezier(0.25, 1, 0.5, 1), fill 0.5s ease, opacity 0.5s ease;
  }
  .text-label {
    font-size: 11px;
    fill: #2c3e50;
    font-weight: bold;
    transition: all 0.5s ease;
  }
  .text-sub {
    font-size: 10px;
    fill: #7f8c8d;
    transition: all 0.5s ease;
  }
  .line-marker {
    stroke: #e74c3c;
    stroke-dasharray: 4,4;
    transition: all 0.5s ease;
  }
  .bracket-path {
    fill: none;
    stroke: #7f8c8d;
    stroke-width: 1.5;
    transition: all 0.5s ease;
  }
</style>
</head>
<body>

<div class="app-container">
