          <!-- 动态对比卡片 -->
          <div class="comparison-card">
            <h3 style="font-size: 13px; margin-bottom: 8px; color: #2c3e50; border-bottom: 2px solid #f0f2f5; padding-bottom: 5px;">📊 实时数据对比分析</h3>
            <div class="comp-row">
              <span class="comp-label">总工资对比 (张 vs 李):</span>
              <span id="comp-sal-ratio" class="comp-val">9000 vs 7000 (多 28.6%)</span>
            </div>
            <div class="comp-row">
              <span class="comp-label">李阿姨计税部分 (超出5000):</span>
              <span id="comp-taxable-li" class="comp-val highlight">2000 元</span>
            </div>
            <div class="comp-row">
              <span class="comp-label">张叔叔计税部分 (超出5000):</span>
              <span id="comp-taxable-zhang" class="comp-val highlight">4000 元</span>
            </div>
            <div class="comp-row">
              <span class="comp-label">个税额对比 (张 vs 李):</span>
              <span id="comp-tax-ratio" class="comp-val" style="color: #e74c3c;">120元 vs 60元 (2.00 倍)</span>
            </div>
          </div>

          <button id="sb-reset-btn" class="btn btn-secondary" style="width: 100%; font-size: 13px; padding: 8px;">重置为默认数据 (7000 vs 9000)</button>
        </div>

        <!-- 右侧动态可视化面板 -->
        <div class="sandbox-visual">
          <svg viewBox="0 0 440 340" id="sandbox-svg">
            <!-- 图例 -->
            <g transform="translate(20, 15)">
              <rect x="0" y="0" width="12" height="12" fill="#2ecc71" rx="2" />
              <text x="18" y="10" font-size="10" fill="#7f8c8d" font-weight="bold">免税额 (5000元)</text>

              <rect x="130" y="0" width="12" height="12" fill="#e67e22" rx="2" />
              <text x="148" y="10" font-size="10" fill="#7f8c8d" font-weight="bold">计税部分</text>

              <rect x="230" y="0" width="12" height="12" fill="#e74c3c" rx="2" />
              <text x="248" y="10" font-size="10" fill="#7f8c8d" font-weight="bold">个税额 (3%)</text>
            </g>

            <!-- 基准线 -->
            <line x1="20" y1="280" x2="420" y2="280" stroke="#bdc3c7" stroke-width="2" />

            <!-- 左侧：工资结构 -->
            <rect id="sb-li-sal-base" class="bar" x="40" y="213.33" width="60" height="66.67" fill="#2ecc71" rx="4" />
            <rect id="sb-li-sal-excess" class="bar" x="40" y="186.67" width="60" height="26.67" fill="#e67e22" rx="4" />

            <rect id="sb-zhang-sal-base" class="bar" x="130" y="213.33" width="60" height="66.67" fill="#2ecc71" rx="4" />
            <rect id="sb-zhang-sal-excess" class="bar" x="130" y="160" width="60" height="53.33" fill="#e67e22" rx="4" />

            <!-- 起征点虚线 -->
            <line x1="20" y1="213.33" x2="210" y2="213.33" stroke="#e74c3c" stroke-width="1.5" stroke-dasharray="3,3" />
            <text x="25" y="205" fill="#e74c3c" font-size="10" font-weight="bold">起征点 5000元</text>

            <text x="70" y="300" text-anchor="middle" class="text-label">李阿姨</text>
            <text x="160" y="300" text-anchor="middle" class="text-label">张叔叔</text>
            <text x="115" y="325" text-anchor="middle" class="text-label" font-size="13" fill="#7f8c8d">月工资结构</text>

            <text id="sb-li-sal-label" x="70" y="175" text-anchor="middle" class="text-label">7000元</text>
            <text id="sb-zhang-sal-label" x="160" y="150" text-anchor="middle" class="text-label">9000元</text>

            <!-- 右侧：个税额 -->
            <rect id="sb-li-tax-bar" class="bar" x="260" y="250" width="50" height="30" fill="#e74c3c" rx="4" />
            <rect id="sb-zhang-tax-bar" class="bar" x="340" y="220" width="50" height="60" fill="#e74c3c" rx="4" />

            <text x="285" y="300" text-anchor="middle" class="text-label">李阿姨</text>
            <text x="365" y="300" text-anchor="middle" class="text-label">张叔叔</text>
            <text x="325" y="325" text-anchor="middle" class="text-label" font-size="13" fill="#7f8c8d">每月个税额</text>

            <text id="sb-li-tax-label" x="285" y="240" text-anchor="middle" class="text-label">60元</text>
            <text id="sb-zhang-tax-label" x="365" y="210" text-anchor="middle" class="text-label">120元</text>
          </svg>

          <!-- 浮动数学规律提示 -->
          <div style="position: absolute; bottom: 10px; left: 10px; right: 10px; font-size: 11px; color: #7f8c8d; line-height: 1.4; background: rgba(255,255,255,0.9); padding: 8px; border-radius: 6px; border: 1px solid #e4e7ed;">
            💡 <strong>数学规律：</strong>由于减去了相同的常数（5000元起征点），<strong>计税部分的倍数关系</strong>永远比<strong>总工资的倍数关系</strong>更极端。这就是“平移效应”！
