<script>
  // 选项卡切换逻辑
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');
  const guidedControls = document.getElementById('guided-controls');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const targetTab = btn.getAttribute('data-tab');

      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));

      btn.classList.add('active');
      document.getElementById(targetTab).classList.add('active');

      // 控制底部导航条的显示与隐藏
      if (targetTab === 'guided-tab') {
        guidedControls.style.display = 'flex';
      } else {
        guidedControls.style.display = 'none';
        updateSandbox(); // 切换到探究页时刷新数据
      }
    });
  });

  // 启发步步练逻辑
  let currentStep = 1;

  function updateStep() {
    // 更新进度点
    for (let i = 1; i <= 4; i++) {
      const dot = document.getElementById(`dot-${i}`);
      if (dot) {
        if (i === currentStep) {
          dot.classList.add('active');
        } else {
          dot.classList.remove('active');
        }
      }
    }

    // 更新按钮状态
    const prevBtn = document.getElementById('prev-btn');
    const nextBtn = document.getElementById('next-btn');
    prevBtn.disabled = (currentStep === 1);
    if (currentStep === 4) {
      nextBtn.textContent = '重新开始';
    } else {
      nextBtn.textContent = '下一步';
    }

    // 更新步骤标题和描述
    const stepTitleNum = document.getElementById('step-title-num');
    const stepTitleText = document.getElementById('step-title-text');
    const stepBodyText = document.getElementById('step-body-text');

    stepTitleNum.textContent = currentStep;

    // 获取SVG元素
    const liSalBase = document.getElementById('li-sal-base');
    const liSalExcess = document.getElementById('li-sal-excess');
    const zhangSalBase = document.getElementById('zhang-sal-base');
    const zhangSalExcess = document.getElementById('zhang-sal-excess');

    const thresholdLine = document.getElementById('threshold-line');
    const thresholdText = document.getElementById('threshold-text');

    const liBaseVal = document.getElementById('li-base-val');
    const liExcessVal = document.getElementById('li-excess-val');
    const zhangBaseVal = document.getElementById('zhang-base-val');
    const zhangExcessVal = document.getElementById('zhang-excess-val');

    const liSalVal = document.getElementById('li-sal-val');
    const zhangSalVal = document.getElementById('zhang-sal-val');

    const liTaxBar = document.getElementById('li-tax-bar');
    const zhangTaxBar = document.getElementById('zhang-tax-bar');
    const liTaxVal = document.getElementById('li-tax-val');
    const zhangTaxVal = document.getElementById('zhang-tax-val');

    const salBracket = document.getElementById('sal-bracket');
    const salRatioText = document.getElementById('sal-ratio-text');
    const taxBracket = document.getElementById('tax-bracket');
    const taxRatioText = document.getElementById('tax-ratio-text');

    // 状态机分支
    if (currentStep === 1) {
      stepTitleText.textContent = '观察总工资';
      stepBodyText.innerHTML = `张叔叔的工资是9000元，李阿姨的工资是7000元。<br><br>计算两人的工资差距：<br><strong style="color:#3498db; font-size:16px;">(9000 - 7000) ÷ 7000 ≈ 28.6%</strong><br><br>张叔叔的工资确实只比李阿姨多不到30%。`;

      // 恢复初始蓝色柱状图
      liSalBase.setAttribute('fill', '#3498db');
      liSalExcess.setAttribute('fill', '#3498db');
      zhangSalBase.setAttribute('fill', '#3498db');
      zhangSalExcess.setAttribute('fill', '#3498db');

      thresholdLine.setAttribute('opacity', '0');
      thresholdText.setAttribute('opacity', '0');

      liBaseVal.setAttribute('opacity', '0');
      liExcessVal.setAttribute('opacity', '0');
      zhangBaseVal.setAttribute('opacity', '0');
      zhangExcessVal.setAttribute('opacity', '0');

      liSalVal.setAttribute('opacity', '1');
      zhangSalVal.setAttribute('opacity', '1');

      liTaxBar.setAttribute('height', '0');
      liTaxBar.setAttribute('y', '280');
      liTaxBar.setAttribute('opacity', '0');
      zhangTaxBar.setAttribute('height', '0');
      zhangTaxBar.setAttribute('y', '280');
      zhangTaxBar.setAttribute('opacity', '0');

      liTaxVal.setAttribute('opacity', '0');
      zhangTaxVal.setAttribute('opacity', '0');

      salBracket.setAttribute('opacity', '0');
      salRatioText.setAttribute('opacity', '0');
      taxBracket.setAttribute('opacity', '0');
      taxRatioText.setAttribute('opacity', '0');

    } else if (currentStep === 2) {
      stepTitleText.textContent = '扣除免税额';
      stepBodyText.innerHTML = `个税起征点是5000元。这意味着，5000元以内的部分是不需要纳税的（<span style="color:#2ecc71;font-weight:bold;">绿色部分</span>）。<br><br>只有超出5000元的部分才需要纳税（<span style="color:#e67e22;font-weight:bold;">橙色部分</span>）：<br>• 李阿姨应纳税部分：<br>&nbsp;&nbsp;<strong>7000 - 5000 = 2000元</strong><br>• 张叔叔应纳税部分：<br>&nbsp;&nbsp;<strong>9000 - 5000 = 4000元</strong><br><br>瞧！<strong>4000元正好是2000元的 <span style="color:#e67e22;font-size:16px;">2 倍</span>！</strong>`;

      // 拆分工资结构颜色
      liSalBase.setAttribute('fill', '#2ecc71');
      liSalExcess.setAttribute('fill', '#e67e22');
      zhangSalBase.setAttribute('fill', '#2ecc71');
      zhangSalExcess.setAttribute('fill', '#e67e22');

      thresholdLine.setAttribute('opacity', '1');
      thresholdText.setAttribute('opacity', '1');

      liBaseVal.setAttribute('opacity', '1');
      liExcessVal.setAttribute('opacity', '1');
      zhangBaseVal.setAttribute('opacity', '1');
      zhangExcessVal.setAttribute('opacity', '1');

      liSalVal.setAttribute('opacity', '0.3');
      zhangSalVal.setAttribute('opacity', '0.3');

      liTaxBar.setAttribute('height', '0');
      liTaxBar.setAttribute('y', '280');
      liTaxBar.setAttribute('opacity', '0');
      zhangTaxBar.setAttribute('height', '0');
      zhangTaxBar.setAttribute('y', '280');
      zhangTaxBar.setAttribute('opacity', '0');

      liTaxVal.setAttribute('opacity', '0');
      zhangTaxVal.setAttribute('opacity', '0');

      salBracket.setAttribute('opacity', '0');
      salRatioText.setAttribute('opacity', '0');
      taxBracket.setAttribute('opacity', '0');
      taxRatioText.setAttribute('opacity', '0');

    } else if (currentStep === 3) {
      stepTitleText.textContent = '计算个税额';
