<script>
    document.addEventListener('DOMContentLoaded', () => {
        const cards = document.querySelectorAll('.formula-card');
        const steps = document.querySelectorAll('.step-box');
        const connector = document.getElementById('connector');
        const stamp = document.getElementById('stamp');
        const book = document.getElementById('book');
        const resetBtn = document.getElementById('resetBtn');
        const successOverlay = document.getElementById('successOverlay');
        const instructionText = document.getElementById('instructionText');
        const toast = document.getElementById('toast');

        let selectedCard = null;
        let step1Correct = false;
        let step2Correct = false;

        // 打乱卡片顺序
        function shuffleCards() {
            const grid = document.getElementById('cardsGrid');
            const cardArray = Array.from(cards);
            cardArray.sort(() => Math.random() - 0.5);
            grid.innerHTML = '';
            cardArray.forEach(card => grid.appendChild(card));
        }

        shuffleCards();

        // 提示框显示
        function showToast(message) {
            toast.textContent = message;
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 2000);
        }

        // 拖拽开始
        cards.forEach(card => {
            card.addEventListener('dragstart', (e) => {
                if (card.classList.contains('placed')) {
                    e.preventDefault();
                    return;
                }
                selectedCard = card;
                card.classList.add('selected');
                e.dataTransfer.setData('text/plain', card.id);
            });

            card.addEventListener('dragend', () => {
                card.classList.remove('selected');
            });

            // 点击选择（适配移动端/触摸屏）
            card.addEventListener('click', () => {
                if (card.classList.contains('placed')) return;

                if (selectedCard === card) {
                    card.classList.remove('selected');
                    selectedCard = null;
                } else {
                    cards.forEach(c => c.classList.remove('selected'));
                    card.classList.add('selected');
                    selectedCard = card;
                }
            });
        });

        // 步骤槽事件
        steps.forEach(step => {
            step.addEventListener('dragover', (e) => {
                e.preventDefault();
                const stepNum = step.getAttribute('data-step');
                if ((stepNum === '1' && step1Correct) || (stepNum === '2' && step2Correct)) return;
                step.classList.add('active-hover');
            });

            step.addEventListener('dragleave', () => {
                step.classList.remove('active-hover');
            });

            step.addEventListener('drop', (e) => {
                e.preventDefault();
                step.classList.remove('active-hover');
                const cardId = e.dataTransfer.getData('text/plain');
                const draggedCard = document.getElementById(cardId);
                if (draggedCard) {
                    checkAndPlace(draggedCard, step);
                }
            });

            // 点击步骤槽放入
            step.addEventListener('click', () => {
                if (selectedCard) {
                    checkAndPlace(selectedCard, step);
                } else {
                    const stepNum = step.getAttribute('data-step');
                    if ((stepNum === '1' && step1Correct) || (stepNum === '2' && step2Correct)) return;
                    showToast('请先在下方选择一张算式卡片');
                }
            });
        });

        // 核心校验逻辑
        function checkAndPlace(card, step) {
            const stepNum = step.getAttribute('data-step');
            const cardTarget = card.getAttribute('data-target');

            // 如果该步骤已经正确，不再接受
            if ((stepNum === '1' && step1Correct) || (stepNum === '2' && step2Correct)) {
                return;
            }

            if (cardTarget === stepNum) {
                // 正确放入
                placeCard(card, step, stepNum);
