        // 放置卡片
        function placeCard(card, step, stepNum) {
            const placeholder = document.getElementById(`placeholder-${stepNum}`);
            placeholder.style.display = 'none';

            // 创建展示在步骤框内的卡片样式
            const displayCard = document.createElement('div');
            displayCard.className = 'formula-card';
            displayCard.style.border = 'none';
            displayCard.style.background = 'transparent';
            displayCard.style.boxShadow = 'none';
            displayCard.style.padding = '0';
            displayCard.style.cursor = 'default';
            displayCard.textContent = card.textContent;

            step.appendChild(displayCard);
            step.classList.add('correct');
            document.getElementById(`status-icon-${stepNum}`).textContent = '✅';

            card.classList.add('placed');
            card.classList.remove('selected');
            card.setAttribute('draggable', 'false');

            if (stepNum === '1') {
                step1Correct = true;
                connector.classList.add('active');
            } else if (stepNum === '2') {
                step2Correct = true;
            }

            selectedCard = null;
            checkWinCondition();
        }

        // 检查是否全部完成
        function checkWinCondition() {
            if (step1Correct && step2Correct) {
                // 触发成功动效
                stamp.classList.add('stamped');
                book.style.transform = 'rotateY(-10deg) scale(1.05)';
                successOverlay.classList.add('show');
                instructionText.innerHTML = '🎉 <strong>太棒了！</strong>你成功完成了“两步法”纳税计算。应纳税额为 <strong>1008元</strong>。';
                showToast('恭喜！两步法通关成功！');
            }
        }

        // 重置功能
        resetBtn.addEventListener('click', () => {
            step1Correct = false;
            step2Correct = false;
            selectedCard = null;

            // 恢复步骤槽
            steps.forEach(step => {
                step.classList.remove('correct', 'active-hover');
                const stepNum = step.getAttribute('data-step');
                document.getElementById(`status-icon-${stepNum}`).textContent = '⚪';
                const placeholder = document.getElementById(`placeholder-${stepNum}`);
                placeholder.style.display = 'block';

                // 移除已放入的卡片元素
                const extraCards = step.querySelectorAll('.formula-card');
                extraCards.forEach(ec => ec.remove());
            });

            // 恢复卡片区
            cards.forEach(card => {
                card.classList.remove('placed', 'selected');
                card.setAttribute('draggable', 'true');
            });

            // 恢复视觉效果
            connector.classList.remove('active');
            stamp.classList.remove('stamped');
            book.style.transform = 'rotateY(-15deg)';
            successOverlay.classList.remove('show');
            instructionText.innerHTML = '💡 <strong>探究任务：</strong>请通过拖拽或点击，将正确的“两步法”算式放入对应的步骤框中。';

            shuffleCards();
            showToast('已重置，重新开始挑战吧！');
        });
    });
</script>

