  <script>
    // 状态机定义
    let currentState = 0;

    const states = {
      0: {
        instruction: "小税务官发现：超出 5000 元起征点的部分按照 3% 税率，缴纳了 45 元个税。<br>让我们用<strong>“逆向两步法”</strong>，一步步还原出员工的月工资吧！",
        leftTitle: "已知税额",
        leftVal: "45 元",
        rightTitle: "等价算式",
        rightVal: "(月工资 - 5000) × 3%",
        tilt: 0,
        render: (container) => {
          const btn = document.createElement('button');
          btn.className = 'btn btn-primary';
          btn.innerHTML = '开始第一步逆推 ➜';
          btn.addEventListener('click', () => transitionTo(1));
          container.appendChild(btn);
        }
      },
      1: {
        instruction: "<strong>【第一步】求计税基数（即超出5000元的部分）</strong><br>等式两边同时除以税率 3%，消除右侧的 '× 3%'：",
        leftTitle: "已知税额",
        leftVal: "45 元",
        rightTitle: "等价算式",
        rightVal: "(月工资 - 5000) × 3%",
        tilt: -4, // 稍微向左倾斜，表示正在对左边进行逆运算
        render: (container) => {
          const formula = document.createElement('div');
          formula.className = 'formula-container';
          formula.innerHTML = `
            <span>45 ÷ </span>
            <input id="input-rate" class="math-input" type="text" placeholder="税率" style="width: 60px;" />
            <span>% = </span>
            <input id="input-base" class="math-input" type="text" placeholder="超出部分" style="width: 90px;" />
            <span>元</span>
          `;
          container.appendChild(formula);

          const btnGroup = document.createElement('div');
          btnGroup.style.display = 'flex';
          btnGroup.style.gap = '8px';

          const btnVerify = document.createElement('button');
          btnVerify.className = 'btn btn-success';
          btnVerify.innerText = '验证计算';

          const btnDemo = document.createElement('button');
          btnDemo.className = 'btn btn-secondary';
          btnDemo.innerText = '直接演示';

          btnGroup.appendChild(btnVerify);
          btnGroup.appendChild(btnDemo);
          container.appendChild(btnGroup);

          // 绑定事件
          btnVerify.addEventListener('click', () => {
            const rateInput = document.getElementById('input-rate');
            const baseInput = document.getElementById('input-base');
            const isRateCorrect = rateInput.value.trim() === '3';
            const isBaseCorrect = baseInput.value.trim() === '1500';

            rateInput.className = `math-input ${isRateCorrect ? 'correct' : 'incorrect'}`;
            baseInput.className = `math-input ${isBaseCorrect ? 'correct' : 'incorrect'}`;

            if (isRateCorrect && isBaseCorrect) {
              playFeedbackSound(true);
              showFeedback("计算正确！等式两边同时除以 3% 后，天平重新恢复平衡！", "success");
              btnVerify.disabled = true;
              btnDemo.disabled = true;
              setTimeout(() => transitionTo(2), 1800);
            } else {
              playFeedbackSound(false);
              showFeedback("算式或结果不正确哦，请再思考一下！提示：税率是 3%。", "error");
            }
          });

          btnDemo.addEventListener('click', () => {
            document.getElementById('input-rate').value = '3';
            document.getElementById('input-base').value = '1500';
            document.getElementById('input-rate').className = 'math-input correct';
            document.getElementById('input-base').className = 'math-input correct';
            playFeedbackSound(true);
            showFeedback("正在演示：45 ÷ 3% = 1500 元", "success");
            btnVerify.disabled = true;
            btnDemo.disabled = true;
            setTimeout(() => transitionTo(2), 1800);
          });
        }
      },
      2: {
        instruction: "<strong>第一步逆推成功！</strong><br>我们算出了超出起征点的部分（计税基数）是 <strong>1500 元</strong>。<br>现在等式简化为：<code>月工资 - 5000 = 1500</code>",
        leftTitle: "计税基数",
        leftVal: "1500 元",
        rightTitle: "等价算式",
        rightVal: "月工资 - 5000",
        tilt: 0, // 恢复平衡
        render: (container) => {
          const btn = document.createElement('button');
          btn.className = 'btn btn-primary';
          btn.innerHTML = '进入第二步逆推 ➜';
          btn.addEventListener('click', () => transitionTo(3));
          container.appendChild(btn);
        }
      },
      3: {
        instruction: "<strong>【第二步】求月工资总额</strong><br>等式两边同时加上起征点 5000 元，消除右侧的 '- 5000'：",
        leftTitle: "计税基数",
        leftVal: "1500 元",
        rightTitle: "等价算式",
        rightVal: "月工资 - 5000",
        tilt: 4, // 稍微向右倾斜
        render: (container) => {
          const formula = document.createElement('div');
          formula.className = 'formula-container';
          formula.innerHTML = `
            <input id="input-prev" class="math-input" type="text" placeholder="计税基数" style="width: 90px;" />
            <span>+</span>
            <input id="input-threshold" class="math-input" type="text" placeholder="起征点" style="width: 80px;" />
            <span>=</span>
            <input id="input-salary" class="math-input" type="text" placeholder="总工资" style="width: 90px;" />
            <span>元</span>
          `;
          container.appendChild(formula);

          const btnGroup = document.createElement('div');
          btnGroup.style.display = 'flex';
          btnGroup.style.gap = '8px';

          const btnVerify = document.createElement('button');
          btnVerify.className = 'btn btn-success';
          btnVerify.innerText = '验证计算';

          const btnDemo = document.createElement('button');
          btnDemo.className = 'btn btn-secondary';
          btnDemo.innerText = '直接演示';

          btnGroup.appendChild(btnVerify);
          btnGroup.appendChild(btnDemo);
          container.appendChild(btnGroup);

          // 绑定事件
          btnVerify.addEventListener('click', () => {
            const prevInput = document.getElementById('input-prev');
            const thresholdInput = document.getElementById('input-threshold');
            const salaryInput = document.getElementById('input-salary');

            const isPrevCorrect = prevInput.value.trim() === '1500';
            const isThresholdCorrect = thresholdInput.value.trim() === '5000';
            const isSalaryCorrect = salaryInput.value.trim() === '6500';

            prevInput.className = `math-input ${isPrevCorrect ? 'correct' : 'incorrect'}`;
            thresholdInput.className = `math-input ${isThresholdCorrect ? 'correct' : 'incorrect'}`;
            salaryInput.className = `math-input ${isSalaryCorrect ? 'correct' : 'incorrect'}`;

            if (isPrevCorrect && isThresholdCorrect && isSalaryCorrect) {
              playFeedbackSound(true);
              showFeedback("计算正确！加上起征点后，成功还原出月工资！", "success");
              btnVerify.disabled = true;
              btnDemo.disabled = true;
              setTimeout(() => transitionTo(4), 1800);
            } else {
              playFeedbackSound(false);
              showFeedback("算式或结果不正确哦，请再试一次！提示：起征点是 5000 元。", "error");
            }
          });

          btnDemo.addEventListener('click', () => {
            document.getElementById('input-prev').value = '1500';
            document.getElementById('input-threshold').value = '5000';
            document.getElementById('input-salary').value = '6500';
            document.getElementById('input-prev').className = 'math-input correct';
            document.getElementById('input-threshold').className = 'math-input correct';
            document.getElementById('input-salary').className = 'math-input correct';
            playFeedbackSound(true);
            showFeedback("正在演示：1500 + 5000 = 6500 元", "success");
            btnVerify.disabled = true;
            btnDemo.disabled = true;
            setTimeout(() => transitionTo(4), 1800);
          });
        }
      },
      4: {
        instruction: "<strong>恭喜！成功逆推出该员工上个月的月工资是 <span style='color:#10b981;'>6500</span> 元！</strong><br><strong>“两步法”思维总结：</strong> 1. 税额 ÷ 税率 = 计税基数； 2. 计税基数 + 起征点 = 总工资。",
        leftTitle: "总工资",
        leftVal: "6500 元",
        rightTitle: "等价算式",
        rightVal: "月工资",
        tilt: 0, // 恢复平衡
        render: (container) => {
          const btn = document.createElement('button');
          btn.className = 'btn btn-primary';
          btn.innerHTML = '重新体验 ↺';
          btn.addEventListener('click', () => transitionTo(0));
          container.appendChild(btn);
        }
      }
    };

    // 状态切换函数
    function transitionTo(stateIndex) {
      currentState = stateIndex;
      const state = states[stateIndex];

      // 更新文本说明
      document.getElementById('instruction').innerHTML = state.instruction;

      // 更新天平托盘内容
      document.getElementById('left-title').innerText = state.leftTitle;
      document.getElementById('left-val').innerText = state.leftVal;
      document.getElementById('right-title').innerText = state.rightTitle;
      document.getElementById('right-val').innerText = state.rightVal;

      // 应用天平倾斜动画
      applyTilt(state.tilt);

      // 重新渲染交互区域
      const interactiveZone = document.getElementById('interactive-zone');
      interactiveZone.innerHTML = '';
      state.render(interactiveZone);

      // 清空提示信息
      clearFeedback();

      // 更新进度指示器
      updateProgressTracker(stateIndex);

      // 触发砝码高亮动画
      const leftWeight = document.getElementById('left-weight');
      const rightWeight = document.getElementById('right-weight');
      leftWeight.classList.add('pulse');
      rightWeight.classList.add('pulse');
      setTimeout(() => {
        leftWeight.classList.remove('pulse');
        rightWeight.classList.remove('pulse');
      }, 1500);
    }

    // 天平倾斜控制
    function applyTilt(degrees) {
      const beam = document.getElementById('beam');
      const leftPan = document.getElementById('left-pan');
      const rightPan = document.getElementById('right-pan');

      // 横梁旋转
      beam.style.transform = `rotate(${degrees}deg)`;
      // 托盘反向旋转，保持水平
      leftPan.style.transform = `rotate(${-degrees}deg)`;
      rightPan.style.transform = `rotate(${-degrees}deg)`;
    }

    // 进度指示器更新
    function updateProgressTracker(stateIndex) {
      // 映射状态到4个进度步骤
      let step = 0;
      if (stateIndex === 0) step = 0;
      else if (stateIndex === 1 || stateIndex === 2) step = 1;
      else if (stateIndex === 3) step = 2;
      else if (stateIndex === 4) step = 3;

      for (let i = 0; i < 4; i++) {
        const el = document.getElementById(`step-indicator-${i}`);
        el.className = 'progress-step';
        if (i < step) {
          el.classList.add('completed');
        } else if (i === step) {
          el.classList.add('active');
        }
      }
    }

    // 提示信息控制
    function showFeedback(text, type) {
      const tip = document.getElementById('feedback-tip');
      tip.innerText = text;
      tip.className = `feedback-tip tip-${type}`;
    }

    function clearFeedback() {
      const tip = document.getElementById('feedback-tip');
      tip.innerText = '';
      tip.className = 'feedback-tip';
    }

    // 声音反馈（使用 Web Audio API，无需外部音频文件）
    function playFeedbackSound(isSuccess) {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (!AudioContext) return;
        const ctx = new AudioContext();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        osc.connect(gain);
        gain.connect(ctx.destination);

        if (isSuccess) {
          // 欢快的成功音效 (C5 -> E5)
          osc.frequency.setValueAtTime(523.25, ctx.currentTime); 
          osc.frequency.setValueAtTime(659.25, ctx.currentTime + 0.12);
          gain.gain.setValueAtTime(0.1, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);
          osc.start();
          osc.stop(ctx.currentTime + 0.4);
        } else {
          // 低沉的失败提示音
          osc.frequency.setValueAtTime(180, ctx.currentTime);
          gain.gain.setValueAtTime(0.15, ctx.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
          osc.start();
          osc.stop(ctx.currentTime + 0.3);
        }
      } catch (e) {
        // 忽略浏览器音频限制报错
      }
    }

    // 初始化启动
    window.addEventListener('DOMContentLoaded', () => {
      transitionTo(0);
    });
  </script>
