        }

        /* 学生小人格子样式 */
        .cell {
            position: relative;
            background-color: #cbd5e1;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.25s ease;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* 绘制小人头像 */
        .cell::before {
            content: '';
            position: absolute;
            top: 20%;
            width: 32%;
            height: 32%;
            background-color: #ffffff;
            border-radius: 50%;
            transition: all 0.25s ease;
        }

        /* 绘制小人身体 */
        .cell::after {
            content: '';
            position: absolute;
            bottom: 12%;
            width: 55%;
            height: 28%;
            background-color: #ffffff;
            border-radius: 6px 6px 0 0;
            transition: all 0.25s ease;
        }

        /* 状态1：整体（蓝色） */
        .cell.whole {
            background-color: var(--primary-color);
        }
        .cell.whole::before, .cell.whole::after {
            background-color: #eff6ff;
        }

        /* 状态2：部分（金色闪烁） */
        .cell.part {
            background-color: var(--gold-color);
            animation: pulse-gold 2s infinite;
            z-index: 2;
        }
        .cell.part::before, .cell.part::after {
            background-color: #fef9c3;
        }

        /* 状态3：未选中变暗 */
        .cell.dimmed {
            background-color: #f1f5f9;
            opacity: 0.35;
        }
        .cell.dimmed::before, .cell.dimmed::after {
            background-color: #cbd5e1;
        }

        /* 状态4：自由探索选中（绿色） */
        .cell.free-active {
            background-color: var(--green-color);
            transform: scale(1.05);
        }
        .cell.free-active::before, .cell.free-active::after {
            background-color: #ecfdf5;
        }

        /* 状态5：自由探索未选中 */
        .cell.free-inactive {
            background-color: #e2e8f0;
        }
