    <script>
        const grid = document.getElementById('student-grid');
        const cards = document.querySelectorAll('.interactive-card');
        const gridStatusTag = document.getElementById('grid-status-tag');
        const legendActiveColor = document.getElementById('legend-active-color');
        const legendActiveText = document.getElementById('legend-active-text');
        const freeCounterBox = document.getElementById('free-counter-box');
        const freeCountSpan = document.getElementById('free-count');
        const freePercentSpan = document.getElementById('free-percent');
        const questionText = document.getElementById('question-text');
        const btnToggleHint = document.getElementById('btn-toggle-hint');
        const hintText = document.getElementById('hint-text');

        // 初始化 100 个格子
        for (let i = 0; i < 100; i++) {
            const cell = document.createElement('div');
            cell.classList.add('cell', 'whole'); // 默认显示整体
            cell.dataset.index = i;
            grid.appendChild(cell);
        }

        const cells = document.querySelectorAll('.cell');

        // 状态变量
        let currentMode = 'whole'; // 'whole', 'part', 'free'
        let freeSelected = new Set(); // 自由探索选中的索引
        let hintVisible = false;

        // 更新视图主函数
        function updateUI() {
            // 1. 重置提示状态
            hintVisible = false;
            hintText.classList.add('hidden');
            btnToggleHint.textContent = '显示思考提示';

            // 2. 更新卡片激活状态
            cards.forEach(card => {
                if (card.dataset.target === currentMode) {
                    card.classList.add('active');
                } else {
                    card.classList.remove('active');
                }
            });

            // 3. 根据模式更新格子样式和图例
            if (currentMode === 'whole') {
                gridStatusTag.textContent = '当前：整体 (100%)';
                gridStatusTag.style.backgroundColor = '#eff6ff';
                gridStatusTag.style.color = 'var(--primary-color)';
                legendActiveColor.style.backgroundColor = 'var(--primary-color)';
                legendActiveText.textContent = '全班人数 (100%)';
                freeCounterBox.style.opacity = '0.5';

                cells.forEach(cell => {
                    cell.className = 'cell whole';
                });

                questionText.innerHTML = '这里的 <strong>100%</strong> 表示什么意思？谁能用“谁占谁的百分之几”来试着说一说？';
                hintText.innerHTML = '<strong>全班总人数</strong> 占 <strong>全班总人数</strong> 的 <strong>100%</strong>';

            } else if (currentMode === 'part') {
                gridStatusTag.textContent = '当前：部分 (5%)';
                gridStatusTag.style.backgroundColor = '#fefce8';
                gridStatusTag.style.color = 'var(--gold-color)';
                legendActiveColor.style.backgroundColor = 'var(--gold-color)';
                legendActiveText.textContent = '喜欢画画的人数 (5%)';
                freeCounterBox.style.opacity = '0.5';

                cells.forEach((cell, index) => {
                    if (index < 5) {
                        cell.className = 'cell part';
                    } else {
                        cell.className = 'cell dimmed';
                    }
                });

                questionText.innerHTML = '这里的 <strong>5%</strong> 表示什么意思？谁能用“<strong>谁</strong>占<strong>谁</strong>的百分之几”来试着说一说？';
                hintText.innerHTML = '<strong>喜欢画画的人数</strong> 占 <strong>全班总人数</strong> 的 <strong>5%</strong>';

            } else if (currentMode === 'free') {
                gridStatusTag.textContent = '当前：自由探索';
                gridStatusTag.style.backgroundColor = '#f0fdf4';
                gridStatusTag.style.color = 'var(--green-color)';
                legendActiveColor.style.backgroundColor = 'var(--green-color)';
                legendActiveText.textContent = '自定义人数';
                freeCounterBox.style.opacity = '1';

                // 更新计数器
                const count = freeSelected.size;
                freeCountSpan.textContent = count;
                freePercentSpan.textContent = count + '%';

                cells.forEach((cell, index) => {
                    if (freeSelected.has(index)) {
                        cell.className = 'cell free-active';
                    } else {
                        cell.className = 'cell free-inactive';
                    }
                });

                questionText.innerHTML = `你当前选中了 <strong>${count}</strong> 个格子，即 <strong>${count}%</strong>。谁能用“谁占谁的百分之几”来说说它的含义？`;
                hintText.innerHTML = `<strong>选中的 ${count} 人</strong> 占 <strong>全班总人数</strong> 的 <strong>${count}%</strong>`;
            }
        }

        // 绑定右侧卡片点击事件
        cards.forEach(card => {
            card.addEventListener('click', () => {
                currentMode = card.dataset.target;
                if (currentMode === 'free' && freeSelected.size === 0) {
                    // 首次进入自由模式，默认选中前5个，方便过渡
                    for (let i = 0; i < 5; i++) freeSelected.add(i);
                }
                updateUI();
            });
        });

        // 绑定左侧格子点击事件（点击任意格子自动进入自由探索模式）
        grid.addEventListener('click', (e) => {
            const cell = e.target.closest('.cell');
            if (!cell) return;

            const index = parseInt(cell.dataset.index);

            if (currentMode !== 'free') {
                // 如果从其他模式切换过来，先同步当前状态
                freeSelected.clear();
                if (currentMode === 'part') {
                    for (let i = 0; i < 5; i++) freeSelected.add(i);
                } else if (currentMode === 'whole') {
                    for (let i = 0; i < 100; i++) freeSelected.add(i);
                }
                currentMode = 'free';
            }

            // 切换选中状态
            if (freeSelected.has(index)) {
                freeSelected.delete(index);
            } else {
                freeSelected.add(index);
            }

            updateUI();
        });

        // 提示按钮点击事件
        btnToggleHint.addEventListener('click', () => {
            hintVisible = !hintVisible;
            if (hintVisible) {
                hintText.classList.remove('hidden');
                btnToggleHint.textContent = '隐藏思考提示';
            } else {
                hintText.classList.add('hidden');
                btnToggleHint.textContent = '显示思考提示';
            }
        });

        // 初始化运行
        updateUI();
    </script>
</body>
