    const feedback = document.getElementById('feedback');
    const resetBtn = document.getElementById('reset-btn');

    let isDragging = false;
    let startX = 0;
    let startY = 0;
    let currentX = 0;
    let currentY = 0;

    // 记录初始位置
    const initialLeft = dragEl.offsetLeft;
    const initialTop = dragEl.offsetTop;

    // 绑定指针事件（兼容鼠标与触摸屏）
    dragEl.addEventListener('pointerdown', onPointerDown);
    targetEl.addEventListener('click', onTargetClick);

    function onPointerDown(e) {
      if (dragEl.classList.contains('success-state')) return;

      isDragging = true;
      dragEl.setPointerCapture(e.pointerId);

      // 减去当前已有的位移，保证拖拽平滑
      startX = e.clientX - currentX;
      startY = e.clientY - currentY;

      dragEl.style.transition = 'none';
      dragEl.classList.add('dragging');
      interactiveArea.classList.add('dragging-active');

      feedback.textContent = "正在拖动：把税款放入营业额中...";
      feedback.className = "feedback-msg";
    }

    // 绑定在 window 上，防止拖拽过快丢失焦点
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);

    function onPointerMove(e) {
      if (!isDragging) return;
      currentX = e.clientX - startX;
      currentY = e.clientY - startY;
      dragEl.style.transform = `translate(${currentX}px, ${currentY}px)`;
    }

    function onPointerUp(e) {
      if (!isDragging) return;
      isDragging = false;
      dragEl.releasePointerCapture(e.pointerId);
      dragEl.classList.remove('dragging');
      interactiveArea.classList.remove('dragging-active');

      // 碰撞检测
      const dragRect = dragEl.getBoundingClientRect();
      const targetRect = targetEl.getBoundingClientRect();

      // 计算税款袋子中心点
      const dragCenter = {
        x: dragRect.left + dragRect.width / 2,
        y: dragRect.top + dragRect.height / 2
      };

      // 判断中心点是否在营业额袋子范围内
      const isInside = (
