      const targetCenterY = (targetEl.offsetTop + targetEl.offsetHeight / 2);

      const dragStartX = initialLeft + dragEl.offsetWidth / 2;
      const dragStartY = initialTop + dragEl.offsetHeight / 2;

      const targetX = targetCenterX - dragStartX;
      const targetY = targetCenterY - dragStartY;

      dragEl.style.transition = 'all 0.6s cubic-bezier(0.25, 1, 0.5, 1)';
      dragEl.style.transform = `translate(${targetX}px, ${targetY}px) scale(0.1)`;
      dragEl.style.opacity = '0';

      // 营业额袋子内部占比显现
      setTimeout(() => {
        taxSlice.style.opacity = '1';
        taxSliceText.style.opacity = '1';
      }, 300);

      // 更新公式
      formulaPart.textContent = "税款";
      formulaPart.className = "formula-item part-active";
      formulaWhole.textContent = "营业额";
      formulaWhole.className = "formula-item whole-active";

      // 反馈信息
      feedback.innerHTML = "太棒了！🎉 观察发现：<strong>税款是营业额的一部分</strong>。<br>所以，是“交的税款”占“营业额”的百分之几。";
      feedback.className = "feedback-msg success-msg";

      resetBtn.classList.remove('hidden');
    }

    // 失败状态
    function triggerFail() {
      dragEl.style.transition = 'transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
      currentX = 0;
      currentY = 0;
      dragEl.style.transform = 'translate(0px, 0px)';

