    <script>
        // 获取DOM元素
        const btnFlat = document.getElementById('btnFlat');
        const btnProp = document.getElementById('btnProp');
        const btnReset = document.getElementById('btnReset');

        const shopCard = document.getElementById('shopCard');
        const shopEmoji = document.getElementById('shopEmoji');
        const shopStatusText = document.getElementById('shopStatusText');
        const shopTax = document.getElementById('shopTax');
        const shopRemain = document.getElementById('shopRemain');

        const supermarketCard = document.getElementById('supermarketCard');
        const supermarketEmoji = document.getElementById('supermarketEmoji');
        const supermarketStatusText = document.getElementById('supermarketStatusText');
        const supermarketTax = document.getElementById('supermarketTax');
        const supermarketRemain = document.getElementById('supermarketRemain');

        const totalTaxCollected = document.getElementById('totalTaxCollected');
        const mainStage = document.getElementById('mainStage');
        const treasuryBox = document.getElementById('treasuryBox');

        // 初始数据
        const shopRevenue = 8000;
        const supermarketRevenue = 1000000;

        // 绑定按钮事件
        btnFlat.addEventListener('click', () => applyTaxScheme('flat'));
        btnProp.addEventListener('click', () => applyTaxScheme('proportional'));
        btnReset.addEventListener('click', resetState);

        // 产生金币飞舞动画
        function spawnCoins(sourceCard, count) {
            const rectSource = sourceCard.getBoundingClientRect();
            const rectTarget = treasuryBox.getBoundingClientRect();
            const stageRect = mainStage.getBoundingClientRect();

            const startX = rectSource.left + rectSource.width / 2 - stageRect.left;
            const startY = rectSource.top + rectSource.height / 2 - stageRect.top;
            const endX = rectTarget.left + rectTarget.width / 2 - stageRect.left;
            const endY = rectTarget.top + rectTarget.height / 2 - stageRect.top;

            for (let i = 0; i < count; i++) {
                setTimeout(() => {
                    const coin = document.createElement('div');
                    coin.className = 'coin-particle';
                    coin.style.left = `${startX}px`;
                    coin.style.top = `${startY}px`;
                    mainStage.appendChild(coin);

                    // 随机控制点，形成弧线轨迹
                    const ctrlX = (startX + endX) / 2 + (Math.random() - 0.5) * 100;
                    const ctrlY = Math.min(startX, endY) - 50 - Math.random() * 50;

                    const duration = 800 + Math.random() * 400;
                    const startTime = performance.now();

                    function animate(now) {
                        const progress = (now - startTime) / duration;
                        if (progress < 1) {
                            // 贝塞尔曲线公式
                            const t = progress;
                            const x = (1 - t) * (1 - t) * startX + 2 * (1 - t) * t * ctrlX + t * t * endX;
                            const y = (1 - t) * (1 - t) * startY + 2 * (1 - t) * t * ctrlY + t * t * endY;
                            coin.style.left = `${x}px`;
                            coin.style.top = `${y}px`;
                            requestAnimationFrame(animate);
                        } else {
                            coin.remove();
                        }
                    }
                    requestAnimationFrame(animate);
                }, i * 80);
            }
        }

        // 执行征税方案
        function applyTaxScheme(scheme) {
            // 重置状态防止叠加
            resetVisuals();

            setTimeout(() => {
                if (scheme === 'flat') {
                    // 方案一：固定征税 10000 元
                    const sTax = 10000;
                    const sRemain = shopRevenue - sTax;
                    const mTax = 10000;
                    const mRemain = supermarketRevenue - mTax;

                    // 小卖部状态：破产
                    shopTax.textContent = '10,000 元';
