                    shopRemain.textContent = `${sRemain.toLocaleString()} 元`;
                    shopRemain.style.color = 'var(--danger-color)';

                    shopCard.classList.add('active-danger');
                    shopEmoji.textContent = '😭';
                    shopEmoji.classList.add('show');
                    shopStatusText.textContent = '入不敷出，被迫破产！';
                    shopStatusText.style.color = 'var(--danger-color)';
                    shopStatusText.classList.add('show');

                    // 大超市状态：毫无影响
                    supermarketTax.textContent = '10,000 元';
                    supermarketRemain.textContent = `${mRemain.toLocaleString()} 元`;

                    supermarketCard.classList.add('active-success');
                    supermarketEmoji.textContent = '😏';
                    supermarketEmoji.classList.add('show');
                    supermarketStatusText.textContent = '九牛一毛，毫无压力';
                    supermarketStatusText.style.color = 'var(--success-color)';
                    supermarketStatusText.classList.add('show');

                    // 动画效果
                    spawnCoins(shopCard, 1); // 勉强飞出一个
                    spawnCoins(supermarketCard, 5); // 飞出少量

                    animateCounter(sTax + mTax);

                } else if (scheme === 'proportional') {
                    // 方案二：按比例征税 (5%)
                    const rate = 0.05;
                    const sTax = shopRevenue * rate;
                    const sRemain = shopRevenue - sTax;
                    const mTax = supermarketRevenue * rate;
                    const mRemain = supermarketRevenue - mTax;

                    // 小卖部状态：合理纳税，正常营业
                    shopTax.textContent = `${sTax.toLocaleString()} 元 (5%)`;
                    shopTax.style.color = 'var(--dark-color)';
                    shopRemain.textContent = `${sRemain.toLocaleString()} 元`;
                    shopRemain.style.color = 'var(--success-color)';

                    shopCard.classList.add('active-success');
                    shopEmoji.textContent = '😊';
                    shopEmoji.classList.add('show');
                    shopStatusText.textContent = '合理纳税，照常营业';
                    shopStatusText.style.color = 'var(--success-color)';
                    shopStatusText.classList.add('show');

                    // 大超市状态：合理纳税，实力雄厚
                    supermarketTax.textContent = `${mTax.toLocaleString()} 元 (5%)`;
                    supermarketTax.style.color = 'var(--danger-color)'; // 纳税大户
                    supermarketRemain.textContent = `${mRemain.toLocaleString()} 元`;
                    supermarketRemain.style.color = 'var(--success-color)';

                    supermarketCard.classList.add('active-success');
                    supermarketEmoji.textContent = '😃';
                    supermarketEmoji.classList.add('show');
                    supermarketStatusText.textContent = '纳税大户，支持国家建设！';
                    supermarketStatusText.style.color = 'var(--success-color)';
                    supermarketStatusText.classList.add('show');

                    // 动画效果
                    spawnCoins(shopCard, 3); // 飞出少量金币
                    spawnCoins(supermarketCard, 25); // 飞出大量金币

                    animateCounter(sTax + mTax);
                }
            }, 100);
        }

        // 计数器动画
        function animateCounter(targetValue) {
            let startValue = 0;
            const duration = 1500;
            const startTime = performance.now();

            function update(now) {
                const progress = Math.min((now - startTime) / duration, 1);
                const currentValue = Math.floor(progress * targetValue);
                totalTaxCollected.textContent = currentValue.toLocaleString();
                if (progress < 1) {
                    requestAnimationFrame(update);
                }
            }
            requestAnimationFrame(update);
        }

        // 清除状态样式
        function resetVisuals() {
            shopCard.className = 'entity-card';
            supermarketCard.className = 'entity-card';
            shopEmoji.className = 'status-overlay';
            supermarketEmoji.className = 'status-overlay';
            shopStatusText.className = 'status-text';
            supermarketStatusText.className = 'status-text';
            totalTaxCollected.textContent = '0';
        }

        // 完全重置
        function resetState() {
            resetVisuals();

            shopTax.textContent = '0 元';
            shopTax.style.color = 'var(--dark-color)';
            shopRemain.textContent = '8,000 元';
            shopRemain.style.color = 'var(--dark-color)';
            shopStatusText.textContent = '正常营业';
            shopStatusText.style.color = 'var(--dark-color)';

            supermarketTax.textContent = '0 元';
            supermarketTax.style.color = 'var(--dark-color)';
            supermarketRemain.textContent = '1,000,000 元';
            supermarketRemain.style.color = 'var(--dark-color)';
            supermarketStatusText.textContent = '正常营业';
            supermarketStatusText.style.color = 'var(--dark-color)';
        }
    </script>
