<body>

  <div class="classroom-container">
    <!-- 头部：情境再现 -->
    <div class="header">
      <h1>税收概念配对互动板</h1>
      <div class="formula-box">
        <span class="highlight">100万元</span>
        <span>×</span>
        <span class="highlight">5%</span>
        <span>=</span>
        <span class="highlight">5万元</span>
      </div>
      <p class="instruction">请点击左侧的<b>数值卡片</b>，再点击右侧对应的<b>专业术语</b>进行连线配对。</p>
    </div>

    <!-- 中部：连线交互区 -->
    <div class="game-board" id="game-board">
      <svg id="svg-canvas"></svg>

      <!-- 左侧：数值卡片 -->
      <div class="column left-col">
        <div class="card" id="val-100" data-side="left" data-match="term-income">
          100万元
          <div class="dot"></div>
        </div>
        <div class="card" id="val-5pct" data-side="left" data-match="term-rate">
          5%
          <div class="dot"></div>
        </div>
        <div class="card" id="val-5wan" data-side="left" data-match="term-tax">
          5万元
          <div class="dot"></div>
        </div>
      </div>

      <!-- 右侧：术语卡片（顺序打乱） -->
      <div class="column right-col">
        <div class="card" id="term-rate" data-side="right" data-match="val-5pct">
          <div class="dot"></div>
          税率
        </div>
        <div class="card" id="term-income" data-side="right" data-match="val-100">
          <div class="dot"></div>
          计税收入
        </div>
        <div class="card" id="term-tax" data-side="right" data-match="val-5wan">
          <div class="dot"></div>
          应纳税额
        </div>
      </div>
    </div>

    <!-- 底部：控制与即时反馈 -->
    <div class="footer">
      <div class="feedback-message" id="feedback-text"></div>
      <button class="btn-reset" id="btn-reset">重新挑战</button>
    </div>
  </div>

  <script>
    // 状态管理
    let selectedLeft = null;
    let selectedRight = null;
    let matchedPairs = []; // 存储已成功配对的ID对：{leftId, rightId}
    let isProcessing = false; // 防止动画期间重复点击

    // DOM 元素
    const svgCanvas = document.getElementById('svg-canvas');
    const gameBoard = document.getElementById('game-board');
    const feedbackText = document.getElementById('feedback-text');
    const btnReset = document.getElementById('btn-reset');
    const cards = document.querySelectorAll('.card');

    // 初始化与事件绑定
    function init() {
      cards.forEach(card => {
        card.addEventListener('click', handleCardClick);
      });
      btnReset.addEventListener('click', resetGame);
      window.addEventListener('resize', drawAllLines);

      // 首次绘制
      setTimeout(drawAllLines, 100);
    }

    // 处理卡片点击
    function handleCardClick(e) {
      if (isProcessing) return;

      const card = e.currentTarget;

      // 如果卡片已经成功配对，则不可点击
      if (card.classList.contains('correct')) return;

      const side = card.dataset.side;

      if (side === 'left') {
        // 切换左侧选择
        if (selectedLeft) {
          selectedLeft.classList.remove('selected');
        }
        if (selectedLeft === card) {
          selectedLeft = null;
        } else {
          selectedLeft = card;
          selectedLeft.classList.add('selected');
        }
      } else {
        // 切换右侧选择
        if (selectedRight) {
          selectedRight.classList.remove('selected');
        }
        if (selectedRight === card) {
          selectedRight = null;
        } else {
          selectedRight = card;
          selectedRight.classList.add('selected');
        }
      }

      // 触发连线绘制（临时预览线）
      drawAllLines();

      // 检查是否凑齐一对
      if (selectedLeft && selectedRight) {
        checkMatch();
      }
    }

    // 检查配对结果
    function checkMatch() {
      isProcessing = true;
      const leftId = selectedLeft.id;
      const rightId = selectedRight.id;
      const expectedMatch = selectedLeft.dataset.match;

      if (rightId === expectedMatch) {
        // 配对正确
        selectedLeft.classList.remove('selected');
        selectedRight.classList.remove('selected');
        selectedLeft.classList.add('correct');
        selectedRight.classList.add('correct');

        matchedPairs.push({ leftId, rightId });

        showFeedback('正确！完美契合。', 'success');

        selectedLeft = null;
        selectedRight = null;
        isProcessing = false;

        drawAllLines();
        checkGameComplete();
      } else {
        // 配对错误
        selectedLeft.classList.add('incorrect');
        selectedRight.classList.add('incorrect');

        // 绘制一条临时的红色错误线
        drawTemporaryErrorLine(selectedLeft, selectedRight);
        showFeedback('配对不正确，再试一次哦！', 'error');

        setTimeout(() => {
          selectedLeft.classList.remove('selected', 'incorrect');
          selectedRight.classList.remove('selected', 'incorrect');
          selectedLeft = null;
          selectedRight = null;
          isProcessing = false;
          drawAllLines();
        }, 1000);
      }
    }

    // 检查是否全部完成
    function checkGameComplete() {
      if (matchedPairs.length === 3) {
        setTimeout(() => {
          showFeedback('🎉 太棒了！你已经成功将所有数值与专业术语精准绑定！', 'success');
        }, 300);
      }
    }

    // 获取锚点的绝对坐标（相对于SVG画布）
    function getDotCoords(cardEl) {
      const dot = cardEl.querySelector('.dot');
      const dotRect = dot.getBoundingClientRect();
      const canvasRect = svgCanvas.getBoundingClientRect();

      return {
        x: dotRect.left - canvasRect.left + dotRect.width / 2,
        y: dotRect.top - canvasRect.top + dotRect.height / 2
      };
    }

    // 绘制贝塞尔曲线
    function createBezierPath(x1, y1, x2, y2) {
      const controlOffset = Math.abs(x2 - x1) * 0.5;
      return `M ${x1} ${y1} C ${x1 + controlOffset} ${y1}, ${x2 - controlOffset} ${y2}, ${x2} ${y2}`;
    }

    // 绘制所有确定的连线和当前选择的预览线
    function drawAllLines() {
      // 清空画布
      svgCanvas.innerHTML = '';

      // 1. 绘制已确定的正确连线
      matchedPairs.forEach(pair => {
        const leftEl = document.getElementById(pair.leftId);
        const rightEl = document.getElementById(pair.rightId);
        if (leftEl && rightEl) {
          const p1 = getDotCoords(leftEl);
          const p2 = getDotCoords(rightEl);
          const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
          path.setAttribute('d', createBezierPath(p1.x, p1.y, p2.x, p2.y));
          path.setAttribute('stroke', '#10b981');
          path.setAttribute('stroke-width', '4');
          path.setAttribute('fill', 'none');
          svgCanvas.appendChild(path);
        }
      });

      // 2. 绘制选择过程中的蓝色引导线
      if (selectedLeft && !selectedRight) {
        // 只有左侧选中，不画完整线，可扩展为随鼠标移动，此处保持简洁，不画线
      } else if (!selectedLeft && selectedRight) {
        // 同上
      }
    }

    // 绘制临时错误红线
    function drawTemporaryErrorLine(leftEl, rightEl) {
      const p1 = getDotCoords(leftEl);
      const p2 = getDotCoords(rightEl);
      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      path.setAttribute('d', createBezierPath(p1.x, p1.y, p2.x, p2.y));
      path.setAttribute('stroke', '#ef4444');
      path.setAttribute('stroke-width', '4');
      path.setAttribute('stroke-dasharray', '8,4');
      path.setAttribute('fill', 'none');
      svgCanvas.appendChild(path);
    }

    // 显示反馈信息
    function showFeedback(msg, type) {
      feedbackText.textContent = msg;
      feedbackText.className = 'feedback-message ' + type;
    }

    // 重置游戏
    function resetGame() {
      selectedLeft = null;
      selectedRight = null;
      matchedPairs = [];
      isProcessing = false;

      cards.forEach(card => {
        card.className = 'card';
      });

      feedbackText.textContent = '';
      feedbackText.className = 'feedback-message';

      drawAllLines();
    }

    // 执行初始化
    init();
  </script>
</body>
