        </div>

        <!-- 角色跑道 -->
        <div class="tracks-container">
            <!-- 跑道1：小李 -->
            <div class="track-row">
                <div class="track-label">小李</div>
                <div class="track-path">
                    <div class="salary-bar-green" id="bar-li-green"></div>
                    <div class="salary-bar-red" id="bar-li-red"></div>
                    <div class="avatar-wrapper" id="avatar-li">
                        <div class="avatar">👦</div>
                        <div class="avatar-tag" id="tag-li">0元</div>
                    </div>
                </div>
            </div>

            <!-- 跑道2：大张 -->
            <div class="track-row">
                <div class="track-label">大张</div>
                <div class="track-path">
                    <div class="salary-bar-green" id="bar-zhang-green"></div>
                    <div class="salary-bar-red" id="bar-zhang-red"></div>
                    <div class="avatar-wrapper" id="avatar-zhang">
                        <div class="avatar">👨‍💼</div>
                        <div class="avatar-tag" id="tag-zhang">0元</div>
                    </div>
                </div>
            </div>
