<script>
    // 获取DOM元素
    const sliderLi = document.getElementById('slider-li');
    const sliderZhang = document.getElementById('slider-zhang');

    const textLiSalary = document.getElementById('text-li-salary');
    const textZhangSalary = document.getElementById('text-zhang-salary');

    const avatarLi = document.getElementById('avatar-li');
    const avatarZhang = document.getElementById('avatar-zhang');

    const tagLi = document.getElementById('tag-li');
    const tagZhang = document.getElementById('tag-zhang');

    const barLiGreen = document.getElementById('bar-li-green');
    const barLiRed = document.getElementById('bar-li-red');
    const barZhangGreen = document.getElementById('bar-zhang-green');
    const barZhangRed = document.getElementById('bar-zhang-red');

    const statusLi = document.getElementById('status-li');
    const statusZhang = document.getElementById('status-zhang');

    const btnReset = document.getElementById('btn-reset');
    const btnDemo1 = document.getElementById('btn-demo1');
    const btnDemo2 = document.getElementById('btn-demo2');

    const rulerTicks = document.getElementById('ruler-ticks');

    // 初始化刻度尺
    function initRuler() {
        rulerTicks.innerHTML = '';
        for (let i = 0; i <= 10000; i += 1000) {
            const pct = i / 10000 * 100;
            const tick = document.createElement('div');
            tick.className = 'tick';
            if (i % 2000 === 0 || i === 5000) {
                tick.classList.add('tick-major');
                tick.setAttribute('data-val', i === 5000 ? '5000(起征点)' : i);
            } else {
                tick.setAttribute('data-val', i);
            }
            tick.style.left = `${pct}%`;
            rulerTicks.appendChild(tick);
        }
    }

    // 更新单个角色的状态
    function updateCharacter(salary, elements) {
        const maxSalary = 10000;
        const threshold = 5000;

        // 计算百分比
        const totalPct = (salary / maxSalary) * 100;

        // 计算绿色和红色条的宽度
        let greenPct = 0;
        let redPct = 0;

        if (salary <= threshold) {
            greenPct = totalPct;
            redPct = 0;
        } else {
            greenPct = 50; // 5000元占10000元的50%
            redPct = ((salary - threshold) / maxSalary) * 100;
        }

        // 更新视图
        elements.avatar.style.left = `${totalPct}%`;
        elements.tag.textContent = `${salary}元`;
        elements.textSalary.textContent = `${salary} 元`;

        elements.barGreen.style.width = `${greenPct}%`;
        elements.barRed.style.width = `${redPct}%`;

        // 更新状态卡片
        if (salary <= threshold) {
            elements.statusBox.className = 'status-box status-free';
            elements.statusBox.innerHTML = `✅ <strong>免税：</strong>工资 ${salary}元 ≤ 起征点 5000元，不需要纳税。`;
        } else {
            const taxable = salary - threshold;
            elements.statusBox.className = 'status-box status-tax';
            elements.statusBox.innerHTML = `⚠️ <strong>需纳税：</strong>超出部分 <strong>${taxable}元</strong> (${salary} - 5000) 需要计算纳税。`;
        }
    }

    // 全局更新
    function updateAll() {
        const valLi = parseInt(sliderLi.value);
        const valZhang = parseInt(sliderZhang.value);

        updateCharacter(valLi, {
            avatar: avatarLi,
            tag: tagLi,
            textSalary: textLiSalary,
            barGreen: barLiGreen,
            barRed: barLiRed,
            statusBox: statusLi
        });

        updateCharacter(valZhang, {
            avatar: avatarZhang,
            tag: tagZhang,
            textSalary: textZhangSalary,
            barGreen: barZhangGreen,
            barRed: barZhangRed,
            statusBox: statusZhang
        });
    }

    // 事件监听
    sliderLi.addEventListener('input', updateAll);
    sliderZhang.addEventListener('input', updateAll);

    // 预设按钮事件
    btnReset.addEventListener('click', () => {
        sliderLi.value = 4800;
        sliderZhang.value = 8000;
        updateAll();
    });

    btnDemo1.addEventListener('click', () => {
        sliderLi.value = 6000;
        updateAll();
    });

    btnDemo2.addEventListener('click', () => {
        sliderZhang.value = 4500;
        updateAll();
    });

    // 初始化运行
    initRuler();
    updateAll();
</script>

</body>
