<body>

<div id="app-container">
    <!-- 头部 -->
    <header>
        <h1>✂️ 工资条“切切乐”</h1>
        <p class="subtitle">月工资 8000 元，起征点 5000 元。<br>请移动剪刀，在正确的位置把工资条切成“免税”和“要交税”两部分！</p>
    </header>

    <!-- 主交互区 -->
    <div class="interactive-area">
        <div class="salary-track" id="salary-track">
            <!-- 剪刀与切割线 -->
            <div class="cutter-container" id="cutter">
                <!-- SVG 剪刀图标 -->
                <svg class="scissors-icon" viewBox="0 0 24 24" fill="none" stroke="#e74c3c" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                    <circle cx="6" cy="6" r="3"></circle>
                    <circle cx="6" cy="18" r="3"></circle>
                    <line x1="20" y1="4" x2="8.12" y2="15.88"></line>
                    <line x1="8.12" y1="8.12" x2="20" y2="20"></line>
                </svg>
                <div class="cut-line"></div>
            </div>

            <!-- 工资条 -->
            <div class="salary-bar-wrapper" id="salary-bar-wrapper">
                <div id="part-left" class="bar-part">
                    <span class="bar-label" id="label-left">总工资</span>
                    <span class="bar-value" id="val-left">8000元</span>
                </div>
                <div id="part-right" class="bar-part">
                    <span class="bar-label" id="label-right"></span>
                    <span class="bar-value" id="val-right"></span>
                </div>
            </div>

            <!-- 刻度尺 -->
            <div class="ruler" id="ruler">
                <!-- 刻度由JS动态生成，确保精确对齐 -->
            </div>
        </div>
    </div>

    <!-- 反馈提示区 -->
    <div class="feedback-box feedback-neutral" id="feedback">
        👈 拖动下方滑块，对准起征点位置 👈
    </div>

    <!-- 控制面板 -->
    <div class="control-panel">
        <div class="slider-container">
            <span class="slider-label">移动剪刀位置：</span>
            <input type="range" id="cut-slider" class="range-slider" min="0" max="8000" step="100" value="4000">
            <div class="current-value-display">
                当前对准：<span id="current-val-text">4000</span> 元
            </div>
        </div>

        <div class="button-group">
            <button class="btn btn-cut" id="btn-cut">咔嚓！切开</button>
            <button class="btn btn-reset" id="btn-reset" disabled>重新来过</button>
        </div>
    </div>
</div>

<script>
    // 获取DOM元素
    const slider = document.getElementById('cut-slider');
    const cutter = document.getElementById('cutter');
    const currentValText = document.getElementById('current-val-text');
    const btnCut = document.getElementById('btn-cut');
    const btnReset = document.getElementById('btn-reset');
    const salaryBarWrapper = document.getElementById('salary-bar-wrapper');
    const partLeft = document.getElementById('part-left');
    const partRight = document.getElementById('part-right');
    const labelLeft = document.getElementById('label-left');
    const valLeft = document.getElementById('val-left');
    const labelRight = document.getElementById('label-right');
    const valRight = document.getElementById('val-right');
    const feedback = document.getElementById('feedback');
    const ruler = document.getElementById('ruler');

    // 教学核心配置
    const TOTAL_SALARY = 8000;
    const TAX_THRESHOLD = 5000; // 起征点
    const TRACK_WIDTH = 640; // 工资条总宽度(px)

    // 初始化刻度尺
    function initRuler() {
        ruler.innerHTML = '';
        const steps = [0, 1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000];
        steps.forEach(val => {
            const mark = document.createElement('div');
            mark.className = 'scale-mark';
            if (val === TAX_THRESHOLD) {
                mark.className = 'scale-mark threshold';
                mark.innerHTML = `起征点<br>${val}`;
            } else {
                mark.innerText = val;
            }
            // 计算百分比位置
            const percent = (val / TOTAL_SALARY) * 100;
            mark.style.left = `${percent}%`;
            ruler.appendChild(mark);
        });
    }

    // 声音合成器 (Web Audio API) - 模拟清脆的剪切声和反馈声
    function playSound(type) {
        try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            if (type === 'cut') {
                // 咔嚓声：高频白噪声+快速衰减
                const bufferSize = ctx.sampleRate * 0.1;
                const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
                const data = buffer.getChannelData(0);
                for (let i = 0; i < bufferSize; i++) {
                    data[i] = Math.random() * 2 - 1;
                }
                const noise = ctx.createBufferSource();
                noise.buffer = buffer;

                const filter = ctx.createBiquadFilter();
                filter.type = 'bandpass';
                filter.frequency.value = 1000;

                const gain = ctx.createGain();
                gain.gain.setValueAtTime(0.6, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.08);

                noise.connect(filter);
                filter.connect(gain);
                gain.connect(ctx.destination);
                noise.start();
            } else if (type === 'success') {
                // 成功音效：欢快的两声和弦
                const now = ctx.currentTime;
                const playTone = (freq, start, duration) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, start);
                    gain.gain.setValueAtTime(0.3, start);
                    gain.gain.exponentialRampToValueAtTime(0.01, start + duration);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start(start);
                    osc.stop(start + duration);
                };
                playTone(523.25, now, 0.15); // C5
                playTone(659.25, now + 0.1, 0.3); // E5
            } else if (type === 'error') {
                // 失败音效：低沉的降调
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(150, ctx.currentTime);
                osc.frequency.linearRampToValueAtTime(80, ctx.currentTime + 0.3);
                gain.gain.setValueAtTime(0.3, ctx.currentTime);
                gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
                osc.connect(gain);
                gain.connect(ctx.destination);
                osc.start();
                osc.stop(ctx.currentTime + 0.3);
            }
        } catch (e) {
            console.log('AudioContext not supported or blocked');
        }
    }

    // 更新剪刀位置
    function updateCutterPosition() {
        const val = parseInt(slider.value);
        currentValText.innerText = val;

        // 计算百分比
        const percent = (val / TOTAL_SALARY) * 100;
        cutter.style.left = `${percent}%`;

        // 动态调整未切开时左右两边的比例，给学生视觉暗示
        if (!salaryBarWrapper.classList.contains('is-split')) {
            partLeft.style.width = `${percent}%`;
            partRight.style.width = `${100 - percent}%`;

            // 动态显示左侧和右侧的临时数值
            if (val > 1000) {
                labelLeft.innerText = "左侧部分";
                valLeft.innerText = `${val}元`;
            } else {
                labelLeft.innerText = "";
                valLeft.innerText = "";
            }

            if (TOTAL_SALARY - val > 1000) {
                labelRight.innerText = "右侧部分";
                valRight.innerText = `${TOTAL_SALARY - val}元`;
            } else {
                labelRight.innerText = "";
                valRight.innerText = "";
            }
        }
    }

    // 执行切割判断
    function executeCut() {
        const val = parseInt(slider.value);

        // 播放剪切动作动画
        cutter.classList.add('cutting');
        playSound('cut');

        setTimeout(() => {
            cutter.classList.remove('cutting');

            if (val === TAX_THRESHOLD) {
                // 切割正确！
                playSound('success');
                salaryBarWrapper.classList.add('is-split');

                // 锁定交互
                slider.disabled = true;
                btnCut.disabled = true;
                btnReset.disabled = false;

                // 确立最终视觉和标签
                partLeft.style.width = "62.5%"; // 5000
                partRight.style.width = "37.5%"; // 3000

                labelLeft.innerText = "免税部分";
                valLeft.innerText = "5000元";

                labelRight.innerText = "应纳税部分";
                valRight.innerText = "3000元";

                // 反馈信息
                feedback.className = "feedback-box feedback-success";
                feedback.innerHTML = "🎉 太棒了！切分完全正确！<br>5000元免税，超出的3000元才需要交税。";
            } else {
                // 切割错误
                playSound('error');
                salaryBarWrapper.classList.add('shake-target');
                feedback.className = "feedback-box feedback-error";

                if (val < TAX_THRESHOLD) {
                    feedback.innerText = `不对哦！起征点是5000元，你只留了${val}元免税，叔叔要多交税啦！`;
                } else {
                    feedback.innerText = `不对哦！起征点是5000元，你留了${val}元免税，国家不同意哦！`;
                }

                setTimeout(() => {
                    salaryBarWrapper.classList.remove('shake-target');
                }, 500);
            }
        }, 300);
    }

    // 重置状态
    function resetGame() {
        salaryBarWrapper.classList.remove('is-split');
        slider.disabled = false;
        btnCut.disabled = false;
        btnReset.disabled = true;
        slider.value = 4000;

        feedback.className = "feedback-box feedback-neutral";
        feedback.innerText = "👈 拖动下方滑块，对准起征点位置 👈";

        updateCutterPosition();
    }

    // 事件监听
    slider.addEventListener('input', updateCutterPosition);
    btnCut.addEventListener('click', executeCut);
    btnReset.addEventListener('click', resetGame);

    // 初始化
    initRuler();
    updateCutterPosition();
</script>

</body>
