    const group5000 = document.getElementById('group-5000');
    const group3000 = document.getElementById('group-3000');
    const infoPanel = document.getElementById('info-panel');

    function setNeutral() {
      btnF1.className = 'formula-card';
      btnF2.className = 'formula-card';
      group5000.className.baseVal = 'group-5000 neutral';
      group3000.className.baseVal = 'group-3000 neutral';
      infoPanel.className = 'info-panel';
