    }

    .card.selected {
      border-color: #3b82f6;
      background-color: #eff6ff;
      box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
    }

    .card-tag {
      position: absolute;
      top: -10px;
      left: 16px;
      background: #3b82f6;
      color: white;
      font-size: 11px;
      padding: 2px 8px;
      border-radius: 10px;
      font-weight: bold;
    }

    .card-content {
      font-size: 16px;
      color: #1e293b;
      font-weight: bold;
      line-height: 1.5;
      margin-top: 4px;
      text-align: center;
    }

    /* 底部控制与反馈区 */
    .footer {
      margin-top: 20px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      min-height: 60px;
    }

    .feedback-box {
      flex: 1;
      margin-right: 20px;
      padding: 12px 20px;
      border-radius: 8px;
      font-size: 16px;
      font-weight: bold;
      display: flex;
      align-items: center;
      gap: 8px;
      opacity: 0;
      transform: translateY(10px);
      transition: all 0.3s ease;
    }

    .feedback-box.show {
      opacity: 1;
      transform: translateY(0);
    }

    .feedback-box.info {
      background-color: #f1f5f9;
      color: #475569;
      border-left: 4px solid #64748b;
    }

    .feedback-box.success {
      background-color: #d1fae5;
      color: #065f46;
      border-left: 4px solid #10b981;
    }

    .feedback-box.error {
      background-color: #fee2e2;
      color: #991b1b;
      border-left: 4px solid #ef4444;
    }

    .btn-reset {
      background-color: #64748b;
      color: white;
      border: none;
      padding: 12px 24px;
      font-size: 16px;
      font-weight: bold;
      border-radius: 8px;
      cursor: pointer;
      transition: background-color 0.2s;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .btn-reset:hover {
      background-color: #475569;
    }

    .btn-reset:active {
      transform: scale(0.98);
    }

    /* 辅助提示动画 */
    @keyframes pulse-green {
      0%, 100% { transform: scale(1); }
      50% { transform: scale(1.05); box-shadow: 0 0 15px rgba(16, 185, 129, 0.4); }
    }

    .pulse-success {
      animation: pulse-green 2s infinite;
    }
