<body>

  <div class="aspect-ratio-container">
    <!-- 头部 -->
    <div class="header">
      <h1>税务专家解题卡片拼图 <span class="badge">六年级 · 百分数应用</span></h1>
      <p>请将右侧的“解题卡片”拖拽或点击放入左侧正确的步骤槽中，理清解题思路！</p>
    </div>

    <!-- 主交互区 -->
    <div class="main-layout">

      <!-- 左侧：步骤槽 -->
      <div class="slots-column">
        <!-- 步骤 1 -->
        <div class="slot-wrapper" id="slot-1" data-expected="card-base">
          <div class="slot-label">
            <span class="step-num">1</span> 第一步：奠定计算基础
          </div>
          <div class="slot-dropzone" id="zone-1">
            <div class="slot-placeholder">请拖入或点击选择卡片放入此处</div>
          </div>
        </div>

        <!-- 步骤 2 -->
        <div class="slot-wrapper" id="slot-2" data-expected="card-tax">
          <div class="slot-label">
            <span class="step-num">2</span> 第二步：计算最终税额
          </div>
          <div class="slot-dropzone" id="zone-2">
            <div class="slot-placeholder">请拖入或点击选择卡片放入此处</div>
          </div>
        </div>
      </div>

      <!-- 中间：流程箭头 -->
      <div class="arrow-column">
        <svg class="flow-arrow" id="flow-arrow" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M19 13l-7 7-7-7m14-6l-7 7-7-7"></path>
        </svg>
      </div>

      <!-- 右侧：卡片池 -->
      <div class="cards-column" id="cards-pool">
        <div class="cards-column-title">待整理的解题卡片</div>

        <!-- 卡片 A -->
        <div class="card" id="card-tax" draggable="true">
          <div class="card-tag">计算公式</div>
          <div class="card-content">计算应纳税额 =<br>计税基数 × 税率</div>
        </div>

        <!-- 卡片 B -->
        <div class="card" id="card-base" draggable="true">
          <div class="card-tag">计算公式</div>
          <div class="card-content">确定计税基数 =<br>总收入 - 免税额</div>
        </div>
      </div>

    </div>

    <!-- 底部控制与反馈 -->
    <div class="footer">
      <div class="feedback-box info" id="feedback-box">
        <span id="feedback-icon">💡</span>
        <span id="feedback-text">试着把卡片放到对应的步骤框里吧！支持拖拽，也可以先点卡片再点目标框。</span>
      </div>
      <button class="btn-reset" id="btn-reset">
        <svg width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" style="vertical-align: middle;">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 1121.21 8H17"></path>
        </svg>
        重置卡片
      </button>
    </div>
  </div>

  <script>
    // 获取DOM元素
    const cards = document.querySelectorAll('.card');
    const slots = document.querySelectorAll('.slot-wrapper');
    const dropzones = document.querySelectorAll('.slot-dropzone');
    const cardsPool = document.getElementById('cards-pool');
    const flowArrow = document.getElementById('flow-arrow');
    const feedbackBox = document.getElementById('feedback-box');
    const feedbackIcon = document.getElementById('feedback-icon');
    const feedbackText = document.getElementById('feedback-text');
    const btnReset = document.getElementById('btn-reset');

    let draggedCard = null;
    let selectedCard = null;

    // Web Audio API 声音合成器
    let audioCtx = null;
    function playSound(type) {
      try {
        if (!audioCtx) {
          audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        }
        if (audioCtx.state === 'suspended') {
          audioCtx.resume();
        }

        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(audioCtx.destination);

        const now = audioCtx.currentTime;

        if (type === 'success') {
          // 欢快的双音符
          osc.type = 'sine';
          osc.frequency.setValueAtTime(523.25, now); // C5
          osc.frequency.setValueAtTime(659.25, now + 0.12); // E5
          gain.gain.setValueAtTime(0.15, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);
          osc.start(now);
          osc.stop(now + 0.4);
        } else if (type === 'error') {
          // 低沉的提示音
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(220, now); // A3
          gain.gain.setValueAtTime(0.2, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
          osc.start(now);
          osc.stop(now + 0.3);
        } else if (type === 'click') {
          // 轻微的点击反馈
          osc.type = 'sine';
          osc.frequency.setValueAtTime(600, now);
          gain.gain.setValueAtTime(0.05, now);
          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.05);
          osc.start(now);
          osc.stop(now + 0.05);
        }
      } catch (e) {
        console.log('Audio context not supported or blocked');
      }
    }

    // 初始化反馈信息
    function showFeedback(type, text) {
      feedbackBox.className = `feedback-box ${type} show`;
      feedbackText.textContent = text;
      if (type === 'success') {
        feedbackIcon.textContent = '🎉';
      } else if (type === 'error') {
        feedbackIcon.textContent = '❌';
      } else {
        feedbackIcon.textContent = '💡';
      }
    }

    // 拖拽开始
    cards.forEach(card => {
      card.addEventListener('dragstart', (e) => {
        draggedCard = card;
        card.classList.add('dragging');
        // 清除点击选择状态
        if (selectedCard) {
          selectedCard.classList.remove('selected');
          selectedCard = null;
        }
      });

      card.addEventListener('dragend', () => {
        card.classList.remove('dragging');
        draggedCard = null;
      });

      // 点击选择逻辑 (适配移动端和黑板触屏)
      card.addEventListener('pointerdown', (e) => {
        // 如果卡片已经在槽里，点击它会退回到池中
        if (card.parentElement.classList.contains('slot-dropzone')) {
          playSound('click');
          cardsPool.appendChild(card);
          checkStatus();
          return;
        }

        playSound('click');
        if (selectedCard === card) {
          card.classList.remove('selected');
          selectedCard = null;
        } else {
          if (selectedCard) {
            selectedCard.classList.remove('selected');
          }
          selectedCard = card;
          card.classList.add('selected');
          showFeedback('info', '已选择卡片，请点击左侧的“第一步”或“第二步”空槽放入。');
        }
      });
    });

    // 放置区逻辑
    slots.forEach(slot => {
      const zone = slot.querySelector('.slot-dropzone');

      // 拖拽悬停
      slot.addEventListener('dragover', (e) => {
        e.preventDefault();
        if (!zone.querySelector('.card')) {
          slot.classList.add('drag-over');
        }
      });

      slot.addEventListener('dragleave', () => {
        slot.classList.remove('drag-over');
      });

      // 拖拽释放
      slot.addEventListener('drop', (e) => {
        e.preventDefault();
        slot.classList.remove('drag-over');

        if (draggedCard && !zone.querySelector('.card')) {
          zone.appendChild(draggedCard);
          playSound('click');
          checkStatus();
        }
      });

      // 点击放置逻辑
      slot.addEventListener('click', () => {
        if (selectedCard && !zone.querySelector('.card')) {
          zone.appendChild(selectedCard);
          selectedCard.classList.remove('selected');
          selectedCard = null;
          playSound('click');
          checkStatus();
        }
      });
    });

    // 点击空白处取消选择
    document.addEventListener('pointerdown', (e) => {
      if (!e.target.closest('.card') && !e.target.closest('.slot-wrapper')) {
        if (selectedCard) {
          selectedCard.classList.remove('selected');
          selectedCard = null;
        }
      }
    });

    // 检查拼图状态
    function checkStatus() {
      const slot1 = document.getElementById('slot-1');
      const slot2 = document.getElementById('slot-2');
      const cardIn1 = slot1.querySelector('.card');
      const cardIn2 = slot2.querySelector('.card');

      // 隐藏占位文本
      togglePlaceholder(slot1, cardIn1);
      togglePlaceholder(slot2, cardIn2);

      // 重置状态样式
      slots.forEach(s => s.className = 'slot-wrapper');

      if (cardIn1 && cardIn2) {
        // 两个槽都放满了，开始校验
        const is1Correct = slot1.dataset.expected === cardIn1.id;
        const is2Correct = slot2.dataset.expected === cardIn2.id;

        if (is1Correct && is2Correct) {
          // 完全正确
          slot1.classList.add('correct');
          slot2.classList.add('correct');
          flowArrow.classList.add('active');
          showFeedback('success', '太棒了！解题第一步是先求出“计税基数”（总收入-免税额），第二步再用“计税基数×税率”求出应纳税额。');
          playSound('success');
          // 增加呼吸灯效果
          slot1.classList.add('pulse-success');
          slot2.classList.add('pulse-success');
        } else {
          // 顺序反了
          slot1.classList.add('incorrect');
          slot2.classList.add('incorrect');
          flowArrow.classList.remove('active');
          showFeedback('error', '顺序好像反了哦！想一想：如果不先算出“计税基数”，第二步能直接计算“应纳税额”吗？');
          playSound('error');
        }
      } else {
        // 未放满
        flowArrow.classList.remove('active');
        slots.forEach(s => {
          s.classList.remove('pulse-success');
        });

        if (cardIn1 || cardIn2) {
          showFeedback('info', '继续把另一张卡片也放好吧！');
        } else {
          showFeedback('info', '试着把卡片放到对应的步骤框里吧！支持拖拽，也可以先点卡片再点目标框。');
        }
      }
    }

    // 控制占位符显示隐藏
    function togglePlaceholder(slotElement, hasCard) {
      const placeholder = slotElement.querySelector('.slot-placeholder');
      if (hasCard) {
        placeholder.style.display = 'none';
      } else {
        placeholder.style.display = 'block';
      }
    }

    // 重置按钮
    btnReset.addEventListener('click', () => {
      playSound('click');
      cards.forEach(card => {
        cardsPool.appendChild(card);
        card.classList.remove('selected');
      });
      selectedCard = null;
      draggedCard = null;

      slots.forEach(slot => {
        slot.className = 'slot-wrapper';
        const placeholder = slot.querySelector('.slot-placeholder');
        placeholder.style.display = 'block';
      });

      flowArrow.classList.remove('active');
      showFeedback('info', '卡片已重置，请重新开始拼图！');
    });

    // 初始化提示
    showFeedback('info', '试着把卡片放到对应的步骤框里吧！支持拖拽，也可以先点卡片再点目标框。');
  </script>
</body>
